(window.BBD=window.BBD||{});BBD["فيلبي"]=[["بولس وتيموثاوس عبدا يسوع المسيح، إلى جميع القديسين في المسيح يسوع، الذين في فيلبي، مع أساقفة وشمامسة.","نعمة لكم وسلام من االله أبينا والرب يسوع المسيح.","أشكر إلهي عند كل ذكري إياكم","دائما في كل أدعيتي، مقدما الطلبة لأجل جميعكم بفرح،","لسبب مشاركتكم في الإنجيل من أول يوم إلى الآن.","واثقا بهذا عينه أن الذي ابتدأ فيكم عملا صالحا يكمل إلى يوم يسوع المسيح.","كما يحق لي أن أفتكر هذا من جهة جميعكم، لأني حافظكم في قلبي، في وثقي، وفي المحاماة عن الإنجيل وتثبيته، أنتم الذين جميعكم شركائي في النعمة.","فإن االله شاهد لي كيف أشتاق إلى جميعكم في أحشاء يسوع المسيح.","وهذا أصليه: أن تزداد محبتكم أيضا أكثر فأكثر في المعرفة وفي كل فهم،","حتى تميزوا الأمور المتخالفة، لكي تكونوا مخلصين وبلا عثرة إلى يوم المسيح،","مملوئين من ثمر البر الذي بيسوع المسيح لمجد االله وحمده.","ثم أريد أن تعلموا أيها الإخوة أن أموري قد آلت أكثر إلى تقدم الإنجيل،","حتى إن وثقي صارت ظاهرة في المسيح في كل دار الولاية وفي باقي الأماكن أجمع.","وأكثر الإخوة، وهم واثقون في الرب بوثقي، يجترئون أكثر على التكلم بالكلمة بلا خوف.","أما قوم فعن حسد وخصام يكرزون بالمسيح، وأما قوم فعن مسرة.","فهؤلاء عن تحزب ينادون بالمسيح لا عن إخلاص، ظانين أنهم يضيفون إلى وثقي ضيقا.","وأولئك عن محبة، عالمين أني موضوع لحماية الإنجيل.","فماذا؟ غير أنه على كل وجه سواء كان بعلة أم بحق ينادى بالمسيح، وبهذا أنا أفرح. بل سأفرح أيضا.","لأني أعلم أن هذا يؤول لي إلى خلاص بطلبتكم ومؤازرة روح يسوع المسيح،","حسب انتظاري ورجائي أني لا أخزى في شيء، بل بكل مجاهرة كما في كل حين، كذلك الآن، يتعظم المسيح في جسدي، سواء كان بحياة أم بموت.","لأن لي الحياة هي المسيح والموت هو ربح.","ولكن إن كانت الحياة في الجسد هي لي ثمر عملي، فماذا أختار؟ لست أدري!","فإني محصور من الاثنين: لي اشتهاء أن أنطلق وأكون مع المسيح. ذاك أفضل جدا.","ولكن أن أبقى في الجسد ألزم من أجلكم.","فإذ أنا واثق بهذا أعلم أني أمكث وأبقى مع جميعكم لأجل تقدمكم وفرحكم في الإيمان،","لكي يزداد افتخاركم في المسيح يسوع في، بواسطة حضوري أيضا عندكم.","فقط عيشوا كما يحق لإنجيل المسيح، حتى إذا جئت ورأيتكم، أو كنت غائبا أسمع أموركم أنكم تثبتون في روح واحد، مجاهدين معا بنفس واحدة لإيمان الإنجيل،","غير مخوفين بشيء من المقاومين، الأمر الذي هو لهم بينة للهلاك، وأما لكم فللخلاص، وذلك من االله.","لأنه قد وهب لكم لأجل المسيح لا أن تؤمنوا به فقط، بل أيضا أن تتألموا لأجله.","إذ لكم الجهاد عينه الذي رأيتموه في، والآن تسمعون في."],["فإن كان وعظ ما في المسيح. إن كانت تسلية ما للمحبة. إن كانت شركة ما في الروح. إن كانت أحشاء ورأفة،","فتمموا فرحي حتى تفتكروا فكرا واحدا ولكم محبة واحدة بنفس واحدة، مفتكرين شيئا واحدا،","لا شيئا بتحزب أو بعجب، بل بتواضع، حاسبين بعضكم البعض أفضل من أنفسهم.","لا تنظروا كل واحد إلى ما هو لنفسه، بل كل واحد إلى ما هو لآخرين أيضا.","فليكن فيكم هذا الفكر الذي في المسيح يسوع أيضا:","الذي إذ كان في صورة االله، لم يحسب خلسة أن يكون معادلا لله.","لكنه أخلى نفسه، آخذا صورة عبد، صائرا في شبه الناس.","وإذ وجد في الهيئة كإنسان، وضع نفسه وأطاع حتى الموت موت الصليب.","لذلك رفعه االله أيضا، وأعطاه اسما فوق كل اسم","لكي تجثو باسم يسوع كل ركبة ممن في السماء ومن على الأرض ومن تحت الأرض،","ويعترف كل لسان أن يسوع المسيح هو رب لمجد االله الآب.","إذا يا أحبائي، كما أطعتم كل حين، ليس كما في حضوري فقط، بل الآن بالأولى جدا في غيابي، تمموا خلاصكم بخوف ورعدة،","لأن االله هو العامل فيكم أن تريدوا وأن تعملوا من أجل المسرة.","افعلوا كل شيء بلا دمدمة ولا مجادلة،","لكي تكونوا بلا لوم، وبسطاء، أولادا الله بلا عيب في وسط جيل معوج وملتو، تضيئون بينهم كأنوار في العالم.","متمسكين بكلمة الحياة لافتخاري في يوم المسيح بأني لم أسع باطلا ولا تعبت باطلا.","لكنني وإن كنت أنسكب أيضا على ذبيحة إيمانكم وخدمته، أسر وأفرح معكم أجمعين.","وبهذا عينه كونوا أنتم مسرورين أيضا وافرحوا معي.","على أني أرجو في الرب يسوع أن أرسل إليكم سريعا تيموثاوس لكي تطيب نفسي إذا عرفت أحوالكم.","لأن ليس لي أحد آخر نظير نفسي يهتم بأحوالكم بإخلاص،","إذ الجميع يطلبون ما هو لأنفسهم لا ما هو ليسوع المسيح.","وأما اختباره فأنتم تعرفون أنه كولد مع أب خدم معي لأجل الإنجيل.","هذا أرجو أن أرسله أول ما أرى أحوالي حالا.","وأثق بالرب أني أنا أيضا سآتي إليكم سريعا.","ولكني حسبت من اللازم أن أرسل إليكم أبفرودتس أخي، والعامل معي، والمتجند معي، ورسولكم، والخادم لحاجتي.","إذ كان مشتاقا إلى جميعكم ومغموما، لأنكم سمعتم أنه كان مريضا.","فإنه مرض قريبا من الموت، لكن االله رحمه. وليس إياه وحده بل إياي أيضا لئلا يكون لي حزن على حزن.","فأرسلته إليكم بأوفر سرعة، حتى إذا رأيتموه تفرحون أيضا وأكون أنا أقل حزنا.","فاقبلوه في الرب بكل فرح، وليكن مثله مكرما عندكم.","لأنه من أجل عمل المسيح قارب الموت، مخاطرا بنفسه، لكي يجبر نقصان خدمتكم لي."],["أخيرا يا إخوتي افرحوا في الرب. كتابة هذه الأمور إليكم ليست علي ثقيلة، وأما لكم فهي مؤمنة.","انظروا الكلاب. انظروا فعلة الشر. انظروا القطع.","لأننا نحن الختان، الذين نعبد االله بالروح، ونفتخر في المسيح يسوع، ولا نتكل على الجسد -","مع أن لي أن أتكل على الجسد أيضا. إن ظن واحد آخر أن يتكل على الجسد فأنا بالأولى.","من جهة الختان مختون في اليوم الثامن، من جنس إسرائيل، من سبط بنيامين، عبراني من العبرانيين. من جهة الناموس فريسي.","من جهة الغيرة مضطهد الكنيسة. من جهة البر الذي في الناموس بلا لوم.","لكن ما كان لي ربحا فهذا قد حسبته من أجل المسيح خسارة.","بل إني أحسب كل شيء أيضا خسارة من أجل فضل معرفة المسيح يسوع ربي، الذي من أجله خسرت كل الأشياء، وأنا أحسبها نفاية لكي أربح المسيح","وأوجد فيه، وليس لي بري الذي من الناموس، بل الذي بإيمان المسيح، البر الذي من االله بالإيمان.","لأعرفه، وقوة قيامته، وشركة آلامه، متشبها بموته،","لعلي أبلغ إلى قيامة الأموات.","ليس أني قد نلت أو صرت كاملا، ولكني أسعى لعلي أدرك الذي لأجله أدركني أيضا المسيح يسوع.","أيها الإخوة، أنا لست أحسب نفسي أني قد أدركت. ولكني أفعل شيئا واحدا: إذ أنا أنسى ما هو وراء وأمتد إلى ما هو قدام.","أسعى نحو الغرض لأجل جعالة دعوة االله العليا في المسيح يسوع.","فليفتكر هذا جميع الكاملين منا، وإن افتكرتم شيئا بخلافه فاالله سيعلن لكم هذا أيضا.","وأما ما قد أدركناه، فلنسلك بحسب ذلك القانون عينه، ونفتكر ذلك عينه.","كونوا متمثلين بي معا أيها الإخوة، ولاحظوا الذين يسيرون هكذا كما نحن عندكم قدوة.","لأن كثيرين يسيرون ممن كنت أذكرهم لكم مرارا، والآن أذكرهم أيضا باكيا، وهم أعداء صليب المسيح،","الذين نهايتهم الهلاك، الذين إلههم بطنهم ومجدهم في خزيهم، الذين يفتكرون في الأرضيات.","فإن سيرتنا نحن هي في السماوات، التي منها أيضا ننتظر مخلصا هو الرب يسوع المسيح،","الذي سيغير شكل جسد تواضعنا ليكون على صورة جسد مجده، بحسب عمل استطاعته أن يخضع لنفسه كل شيء."],["إذا يا إخوتي الأحباء والمشتاق إليهم، يا سروري وإكليلي، اثبتوا هكذا في الرب أيها الأحباء.","أطلب إلى أفودية وأطلب إلى سنتيخي أن تفتكرا فكرا واحدا في الرب.","نعم أسألك أنت أيضا، يا شريكي المخلص، ساعد هاتين اللتين جاهدتا معي في الإنجيل، مع أكليمندس أيضا وباقي العاملين معي، الذين أسماؤهم في سفر الحياة.","افرحوا في الرب كل حين وأقول أيضا افرحوا.","ليكن حلمكم معروفا عند جميع الناس. الرب قريب.","لا تهتموا بشيء، بل في كل شيء بالصلاة والدعاء مع الشكر، لتعلم طلباتكم لدى االله.","وسلام االله الذي يفوق كل عقل يحفظ قلوبكم وأفكاركم في المسيح يسوع.","أخيرا أيها الإخوة كل ما هو حق، كل ما هو جليل، كل ما هو عادل، كل ما هو طاهر، كل ما هو مسر، كل ما صيته حسن - إن كانت فضيلة وإن كان مدح، ففي هذه افتكروا.","وما تعلمتموه، وتسلمتموه، وسمعتموه، ورأيتموه في، فهذا افعلوا، وإله السلام يكون معكم.","ثم إني فرحت بالرب جدا لأنكم الآن قد أزهر أيضا مرة اعتناؤكم بي الذي كنتم تعتنونه ولكن لم تكن لكم فرصة.","ليس أني أقول من جهة احتياج، فإني قد تعلمت أن أكون مكتفيا بما أنا فيه.","أعرف أن أتضع وأعرف أيضا أن أستفضل. في كل شيء وفي جميع الأشياء قد تدربت أن أشبع وأن أجوع، وأن أستفضل وأن أنقص.","أستطيع كل شيء في المسيح الذي يقويني.","غير أنكم فعلتم حسنا إذ اشتركتم في ضيقتي.","وأنتم أيضا تعلمون أيها الفيلبيون أنه في بداءة الإنجيل، لما خرجت من مكدونية، لم تشاركني كنيسة واحدة في حساب العطاء والأخذ إلا أنتم وحدكم.","فإنكم في تسالونيكي أيضا أرسلتم إلي مرة ومرتين لحاجتي.","ليس أني أطلب العطية، بل أطلب الثمر المتكاثر لحسابكم.","ولكني قد استوفيت كل شيء واستفضلت. قد امتلأت إذ قبلت من أبفرودتس الأشياء التي من عندكم، نسيم رائحة طيبة، ذبيحة مقبولة مرضية عند االله.","فيملأ إلهي كل احتياجكم بحسب غناه في المجد في المسيح يسوع.","ولله وأبينا المجد إلى دهر الداهرين. آمين.","سلموا على كل قديس في المسيح يسوع. يسلم عليكم الإخوة الذين معي.","يسلم عليكم جميع القديسين ولا سيما الذين من بيت قيصر.","نعمة ربنا يسوع المسيح مع جميعكم. آمين )كتبت إلى أهل فيلبي من رومية على يد أبفرودتس(. رسالة بولس الرسول إلى أهل كولوسي"]];
BBD["كولوسي"]=[["بولس، رسول يسوع المسيح بمشيئة االله، وتيموثاوس الأخ،","إلى القديسين في كولوسي، والإخوة المؤمنين في المسيح. نعمة لكم وسلام من االله أبينا والرب يسوع المسيح.","نشكر االله وأبا ربنا يسوع المسيح كل حين، مصلين لأجلكم،","إذ سمعنا إيمانكم بالمسيح يسوع، ومحبتكم لجميع القديسين،","من أجل الرجاء الموضوع لكم في السماوات الذي سمعتم به قبلا في كلمة حق الإنجيل،","الذي قد حضر إليكم كما في كل العالم أيضا، وهو مثمر كما فيكم أيضا منذ يوم سمعتم وعرفتم نعمة االله بالحقيقة.","كما تعلمتم ايضا من ابفراس العبد الحبيب معنا، الذي هو خادم امين للمسيح لأجلكم،","الذي اخبرنا ايضا بمحبتكم في الروح.","من أجل ذلك نحن أيضا، منذ يوم سمعنا، لم نزل مصلين وطالبين لأجلكم ان تمتلئوا من معرفة مشيئته، في كل حكمة وفهم روحي","لتسلكوا كما يحق للرب، في كل رضى، مثمرين في كل عمل صالح، ونامين في معرفة االله،","متقوين بكل قوة بحسب قدرة مجده، لكل صبر وطول اناة بفرح،","شاكرين الآب الذي اهلنا لشركة ميراث القديسين في النور،","الذي انقذنا من سلطان الظلمة ونقلنا الى ملكوت ابن محبته،","الذي لنا فيه الفداء، بدمه غفران الخطايا،","الذي هو صورة االله غير المنظور، بكر كل خليقة.","فإنه فيه خلق الكل: ما في السماوات وما على الأرض، ما يرى وما لا يرى، سواء كان عروشا ام سيادات ام رياسات ام سلاطين. الكل به وله قد خلق.","الذي هو قبل كل شيء، وفيه يقوم الكل","وهو رأس الجسد: الكنيسة. الذي هو البداءة، بكر من الأموات، لكي يكون هو متقدما في كل شيء.","لأنه فيه سر ان يحل كل الملء،","وأن يصالح به الكل لنفسه، عاملا الصلح بدم صليبه، بواسطته، سواء كان ما على الأرض ام ما في السماوات.","وأنتم الذين كنتم قبلا اجنبيين وأعداء في الفكر، في الأعمال الشريرة، قد صالحكم الآن","في جسم بشريته بالموت، ليحضركم قديسين وبلا لوم ولا شكوى امامه،","إن ثبتم على الإيمان، متأسسين وراسخين وغير منتقلين عن رجاء الإنجيل، الذي سمعتموه، المكروز به في كل الخليقة التي تحت السماء، الذي صرت انا بولس خادما له،","الذي الآن افرح في الامي لأجلكم، وأكمل نقائص شدائد المسيح في جسمي لأجل جسده: الذي هو الكنيسة،","التي صرت انا خادما لها، حسب تدبير االله المعطى لي لأجلكم، لتتميم كلمة االله.","السر المكتوم منذ الدهور ومنذ الأجيال، لكنه الآن قد اظهر لقديسيه،","الذين اراد االله ان يعرفهم ما هو غنى مجد هذا السر في الأمم، الذي هو المسيح فيكم رجاء المجد.","الذي ننادي به منذرين كل انسان، ومعلمين كل انسان، بكل حكمة، لكي نحضر كل انسان كاملا في المسيح يسوع.","الأمر الذي لأجله اتعب ايضا مجاهدا، بحسب عمله الذي يعمل في بقوة."],["فإني اريد ان تعلموا اي جهاد لي لأجلكم، ولأجل الذين في لاودكية، وجميع الذين لم يروا وجهي في الجسد،","لكي تتعزى قلوبهم مقترنة في المحبة لكل غنى يقين الفهم، لمعرفة سر االله الآب والمسيح،","المذخر فيه جميع كنوز الحكمة والعلم.","وإنما اقول هذا لئلا يخدعكم احد بكلام ملق،","فإني وإن كنت غائبا في الجسد لكني معكم في الروح، فرحا، وناظرا ترتيبكم ومتانة ايمانكم في المسيح.","فكما قبلتم المسيح يسوع الرب اسلكوا فيه،","متأصلين ومبنيين فيه، وموطدين في الإيمان، كما علمتم، متفاضلين فيه بالشكر.","انظروا ان لا يكون احد يسبيكم بالفلسفة وبغرور باطل، حسب تقليد الناس، حسب اركان العالم، وليس حسب المسيح.","فإنه فيه يحل كل ملء اللاهوت جسديا.","وأنتم مملوؤون فيه، الذي هو رأس كل رياسة وسلطان.","وبه ايضا ختنتم ختانا غير مصنوع بيد، بخلع جسم خطايا البشرية، بختان المسيح.","مدفونين معه في المعمودية، التي فيها اقمتم ايضا معه بإيمان عمل االله، الذي اقامه من الأموات.","وإذ كنتم امواتا في الخطايا وغلف جسدكم، احياكم معه، مسامحا لكم بجميع الخطايا،","إذ محا الصك الذي علينا في الفرائض، الذي كان ضدا لنا، وقد رفعه من الوسط مسمرا اياه بالصليب،","إذ جرد الرياسات والسلاطين اشهرهم جهارا، ظافرا بهم فيه.","فلا يحكم عليكم احد في أكل او شرب، او من جهة عيد او هلال او سبت،","التي هي ظل الأمور العتيدة، وأما الجسد فللمسيح.","لا يخسركم احد الجعالة، راغبا في التواضع وعبادة الملائكة، متداخلا في ما لم ينظره، منتفخا باطلا من قبل ذهنه الجسدي،","وغير متمسك بالرأس الذي منه كل الجسد بمفاصل وربط، متوازرا ومقترنا ينمو نموا من االله.","إذا ان كنتم قد متم مع المسيح عن اركان العالم، فلماذا كأنكم عائشون في العالم، تفرض عليكم فرائض:","لا تمس، ولا تذق، ولا تجس؟","التي هي جميعها للفناء في الاستعمال، حسب وصايا وتعاليم الناس،","التي لها حكاية حكمة، بعبادة نافلة، وتواضع، وقهر الجسد، ليس بقيمة ما من جهة اشباع البشرية."],["فإن كنتم قد قمتم مع المسيح فاطلبوا ما فوق، حيث المسيح جالس عن يمين االله.","اهتموا بما فوق لا بما على الأرض،","لأنكم قد متم وحياتكم مستترة مع المسيح في االله.","متى اظهر المسيح حياتنا، فحينئذ تظهرون انتم ايضا معه في المجد.","فأميتوا اعضاءكم التي على الأرض: الزنا، النجاسة، الهوى، الشهوة الردية، الطمع الذي هو عبادة الأوثان،","الأمور التي من اجلها يأتي غضب االله على ابناء المعصية،","الذين بينهم انتم ايضا سلكتم قبلا، حين كنتم تعيشون فيها.","وأما الآن فاطرحوا عنكم انتم ايضا الكل: الغضب، السخط، الخبث، التجديف، الكلام القبيح من افواهكم.","لا تكذبوا بعضكم على بعض، اذ خلعتم الإنسان العتيق مع اعماله،","ولبستم الجديد الذي يتجدد للمعرفة حسب صورة خالقه،","حيث ليس يوناني ويهودي، ختان وغرلة، بربري سكيثي، عبد حر، بل المسيح الكل وفي الكل.","فالبسوا كمختاري االله القديسين المحبوبين احشاء رأفات، ولطفا، وتواضعا، ووداعة، وطول اناة،","محتملين بعضكم بعضا، ومسامحين بعضكم بعضا ان كان لأحد على احد شكوى. كما غفر لكم المسيح هكذا انتم ايضا.","وعلى جميع هذه البسوا المحبة التي هي رباط الكمال.","وليملك في قلوبكم سلام االله الذي اليه دعيتم في جسد واحد، وكونوا شاكرين.","لتسكن فيكم كلمة المسيح بغنى، وأنتم بكل حكمة معلمون ومنذرون بعضكم بعضا، بمزامير وتسابيح وأغاني روحية، بنعمة، مترنمين في قلوبكم للرب.","وكل ما عملتم بقول او فعل، فاعملوا الكل باسم الرب يسوع، شاكرين االله والآب به.","أيتها النساء، اخضعن لرجالكن كما يليق في الرب.","أيها الرجال، احبوا نساءكم، ولا تكونوا قساة عليهن","أيها الأولاد، اطيعوا والديكم في كل شيء لأن هذا مرضي في الرب.","أيها الآباء، لا تغيظوا اولادكم لئلا يفشلوا.","أيها العبيد، اطيعوا في كل شيء سادتكم حسب الجسد، لا بخدمة العين كمن يرضي الناس، بل ببساطة القلب، خائفين الرب.","وكل ما فعلتم فاعملوا من القلب، كما للرب ليس للناس،","عالمين انكم من الرب ستأخذون جزاء الميراث، لأنكم تخدمون الرب المسيح.","وأما الظالم فسينال ما ظلم به، وليس محاباة."],["أيها السادة، قدموا للعبيد العدل والمساواة، عالمين ان لكم انتم ايضا سيدا في السماوات.","واظبوا على الصلاة ساهرين فيها بالشكر،","مصلين في ذلك لأجلنا نحن ايضا، ليفتح الرب لنا بابا للكلام، لنتكلم بسر المسيح، الذي من اجله انا موثق ايضا،","كي اظهره كما يجب ان اتكلم.","اسلكوا بحكمة من جهة الذين هم من خارج، مفتدين الوقت.","ليكن كلامكم كل حين بنعمة، مصلحا بملح، لتعلموا كيف يجب ان تجاوبوا كل واحد.","جميع احوالي سيعرفكم بها تيخيكس الأخ الحبيب، والخادم الأمين، والعبد معنا في الرب،","الذي ارسلته اليكم لهذا عينه، ليعرف احوالكم ويعزي قلوبكم،","مع انسيمس الأخ الأمين الحبيب الذي هو منكم. هما سيعرفانكم بكل ما ههنا.","يسلم عليكم ارسترخس المأسور معي، ومرقس ابن اخت برنابا، الذي اخذتم لأجله وصايا. ان اتى اليكم فاقبلوه.","ويسوع المدعو يسطس، الذين هم من الختان. هؤلاء هم وحدهم العاملون معي لملكوت االله، الذين صاروا لي تسلية.","يسلم عليكم ابفراس، الذي هو منكم، عبد للمسيح، مجاهد كل حين لأجلكم بالصلوات، لكي تثبتوا كاملين وممتلئين في كل مشيئة االله.","فإني اشهد فيه ان له غيرة كثيرة لأجلكم، ولأجل الذين في لاودكية، والذين في هيرابوليس.","يسلم عليكم لوقا الطبيب الحبيب، وديماس.","سلموا على الإخوة الذين في لاودكية، وعلى نمفاس وعلى الكنيسة التي في بيته.","ومتى قرئت عندكم هذه الرسالة فاجعلوها تقرأ ايضا في كنيسة اللاودكيين، والتي من لاودكية تقرأونها انتم ايضا.","وقولوا لأرخبس: »انظر الى الخدمة التي قبلتها في الرب لكي تتممها«.","السلام بيدي انا بولس. اذكروا وثقي. النعمة معكم. امين. )كتبت الى اهل كولوسي من رومية بيد تيخيكس وأنسيمس( KO رسالة بولس الرسول الأولى إلى أهل تسالونيكي"]];
BBD["تسالونيكي الأولى"]=[["بولس وسلوانس وتيموثاوس، إلى كنيسة التسالونيكيين، في االله الآب والرب يسوع المسيح. نعمة لكم وسلام من االله أبينا والرب يسوع المسيح.","نشكر االله كل حين من جهة جميعكم، ذاكرين إياكم في صلواتنا،","متذكرين بلا انقطاع عمل إيمانكم، وتعب محبتكم، وصبر رجائكم، ربنا يسوع المسيح، أمام االله وأبينا.","عالمين أيها الإخوة المحبوبون من االله اختياركم،","أن إنجيلنا لم يصر لكم بالكلام فقط، بل بالقوة أيضا، وبالروح القدس، وبيقين شديد، كما تعرفون أي رجال كنا بينكم من أجلكم.","وأنتم صرتم متمثلين بنا وبالرب، إذ قبلتم الكلمة في ضيق كثير، بفرح الروح القدس،","حتى صرتم قدوة لجميع الذين يؤمنون في مكدونية وفي أخائية.","لأنه من قبلكم قد أذيعت كلمة الرب، ليس في مكدونية وأخائية فقط، بل في كل مكان أيضا قد ذاع إيمانكم باالله، حتى ليس لنا حاجة أن نتكلم شيئا.","لأنهم هم يخبرون عنا أي دخول كان لنا إليكم، وكيف رجعتم إلى االله من الأوثان لتعبدوا االله الحي الحقيقي،","وتنتظروا ابنه من السماء، الذي أقامه من الأموات، يسوع، الذي ينقذنا من الغضب الآتي."],["لأنكم أنتم أيها الإخوة تعلمون دخولنا إليكم أنه لم يكن باطلا،","بل بعد ما تألمنا قبلا وبغي علينا كما تعلمون، في فيلبي، جاهرنا في إلهنا أن نكلمكم بإنجيل االله، في جهاد كثير.","لأن وعظنا ليس عن ضلال، ولا عن دنس، ولا بمكر،","بل كما استحسنا من االله أن نؤتمن على الإنجيل هكذا نتكلم، لا كأننا نرضي الناس بل االله الذي يختبر قلوبنا.","فإننا لم نكن قط في كلام تملق كما تعلمون، ولا في علة طمع. االله شاهد.","ولا طلبنا مجدا من الناس، لا منكم ولا من غيركم مع أننا قادرون أن نكون في وقار كرسل المسيح.","بل كنا مترفقين في وسطكم كما تربي المرضعة أولادها،","هكذا إذ كنا حانين إليكم كنا نرضى أن نعطيكم، لا إنجيل االله فقط بل أنفسنا أيضا، لأنكم صرتم محبوبين إلينا.","فإنكم تذكرون أيها الإخوة تعبنا وكدنا، إذ كنا نكرز لكم بإنجيل االله، ونحن عاملون ليلا ونهارا كي لا نثقل على أحد منكم.","أنتم شهود، واالله، كيف بطهارة وببر وبلا لوم كنا بينكم أنتم المؤمنين.","كما تعلمون كيف كنا نعظ كل واحد منكم كالأب لأولاده، ونشجعكم،","ونشهدكم لكي تسلكوا كما يحق لله الذي دعاكم إلى ملكوته ومجده.","من أجل ذلك نحن أيضا نشكر االله بلا انقطاع، لأنكم إذ تسلمتم منا كلمة خبر من االله، قبلتموها لا ككلمة أناس، بل كما هي بالحقيقة ككلمة االله، التي تعمل أيضا فيكم أنتم المؤمنين.","فإنكم أيها الإخوة صرتم متمثلين بكنائس االله التي هي في اليهودية في المسيح يسوع، لأنكم تألمتم أنتم أيضا من أهل عشيرتكم تلك الآلام عينها كما هم أيضا من اليهود،","الذين قتلوا الرب يسوع وأنبياءهم، واضطهدونا نحن. وهم غير مرضين لله وأضداد لجميع الناس","يمنعوننا عن أن نكلم الأمم لكي يخلصوا حتى يتمموا خطاياهم كل حين. ولكن قد أدركهم الغضب إلى النهاية.","وأما نحن أيها الإخوة، فإذ قد فقدناكم زمان ساعة، بالوجه لا بالقلب، اجتهدنا أكثر باشتهاء كثير أن نرى وجوهكم.","لذلك أردنا أن نأتي إليكم أنا بولس مرة ومرتين. وإنما عاقنا الشيطان.","لأن من هو رجاؤنا وفرحنا وإكليل افتخارنا؟ أم لستم أنتم أيضا أمام ربنا يسوع المسيح في مجيئه؟","لأنكم أنتم مجدنا وفرحنا."],["لذلك إذ لم نحتمل أيضا استحسنا أن نترك في أثينا وحدنا.","فأرسلنا تيموثاوس أخانا، وخادم االله، والعامل معنا في إنجيل المسيح، حتى يثبتكم ويعظكم لأجل إيمانكم،","كي لا يتزعزع أحد في هذه الضيقات. فإنكم أنتم تعلمون أننا موضوعون لهذا.","لأننا لما كنا عندكم سبقنا فقلنا لكم: إننا عتيدون أن نتضايق، كما حصل أيضا، وأنتم تعلمون.","من أجل هذا إذ لم أحتمل أيضا، أرسلت لكي أعرف إيمانكم، لعل المجرب يكون قد جربكم، فيصير تعبنا باطلا.","وأما الآن فإذ جاء إلينا تيموثاوس من عندكم، وبشرنا بإيمانكم ومحبتكم، وبأن عندكم ذكرا لنا حسنا كل حين، وأنتم مشتاقون أن ترونا، كما نحن أيضا أن نراكم،","فمن أجل هذا تعزينا أيها الإخوة من جهتكم في ضيقتنا وضرورتنا بإيمانكم.","لأننا الآن نعيش إن ثبتم أنتم في الرب.","لأنه أي شكر نستطيع أن نعوض إلى االله من جهتكم عن كل الفرح الذي نفرح به من أجلكم قدام إلهنا؟","طالبين ليلا ونهارا أوفر طلب أن نرى وجوهكم، ونكمل نقائص إيمانكم.","واالله نفسه أبونا وربنا يسوع المسيح يهدي طريقنا إليكم.","والرب ينميكم ويزيدكم في المحبة بعضكم لبعض وللجميع، كما نحن أيضا لكم،","لكي يثبت قلوبكم بلا لوم في القداسة، أمام االله أبينا في مجيء ربنا يسوع المسيح مع جميع قديسيه."],["فمن ثم أيها الإخوة نسألكم ونطلب إليكم في الرب يسوع، أنكم كما تسلمتم منا كيف يجب أن تسلكوا وترضوا االله، تزدادون أكثر.","لأنكم تعلمون أية وصايا أعطيناكم بالرب يسوع.","لأن هذه هي إرادة االله: قداستكم. أن تمتنعوا عن الزنا،","أن يعرف كل واحد منكم أن يقتني إناءه بقداسة وكرامة،","لا في هوى شهوة كالأمم الذين لا يعرفون االله.","أن لا يتطاول أحد ويطمع على أخيه في هذا الأمر، لأن الرب منتقم لهذه كلها كما قلنا لكم قبلا وشهدنا.","لأن االله لم يدعنا للنجاسة بل في القداسة.","إذا من يرذل لا يرذل إنسانا، بل االله الذي أعطانا أيضا روحه القدوس.","وأما المحبة الأخوية فلا حاجة لكم أن أكتب إليكم عنها، لأنكم أنفسكم متعلمون من االله أن يحب بعضكم بعضا.","فإنكم تفعلون ذلك أيضا لجميع الإخوة الذين في مكدونية كلها. وإنما أطلب إليكم أيها الإخوة أن تزدادوا أكثر،","وأن تحرصوا على أن تكونوا هادئين، وتمارسوا أموركم الخاصة، وتشتغلوا بأيديكم أنتم كما أوصيناكم،","لكي تسلكوا بلياقة عند الذين هم من خارج، ولا تكون لكم حاجة إلى أحد.","ثم لا أريد أن تجهلوا أيها الإخوة من جهة الراقدين، لكي لا تحزنوا كالباقين الذين لا رجاء لهم.","لأنه إن كنا نؤمن أن يسوع مات وقام، فكذلك الراقدون بيسوع سيحضرهم االله أيضا معه.","فإننا نقول لكم هذا بكلمة الرب: إننا نحن الأحياء الباقين إلى مجيء الرب لا نسبق الراقدين.","لأن الرب نفسه سوف ينزل من السماء بهتاف، بصوت رئيس ملائكة وبوق االله، والأموات في المسيح سيقومون أولا.","ثم نحن الأحياء الباقين سنخطف جميعا معهم في السحب لملاقاة الرب في الهواء، وهكذا نكون كل حين مع الرب.","لذلك عزوا بعضكم بعضا بهذا الكلام."],["وأما الأزمنة والأوقات فلا حاجة لكم أيها الإخوة أن أكتب إليكم عنها،","لأنكم أنتم تعلمون بالتحقيق أن يوم الرب كلص في الليل هكذا يجيء.","لأنه حينما يقولون: »سلام وأمان« حينئذ يفاجئهم هلاك بغتة، كالمخاض للحبلى، فلا ينجون.","وأما أنتم أيها الإخوة فلستم في ظلمة حتى يدرككم ذلك اليوم كلص.","جميعكم أبناء نور وأبناء نهار. لسنا من ليل ولا ظلمة.","فلا ننم إذا كالباقين، بل لنسهر ونصح،","لأن الذين ينامون فبالليل ينامون، والذين يسكرون فبالليل يسكرون.","وأما نحن الذين من نهار، فلنصح لابسين درع الإيمان والمحبة، وخوذة هي رجاء الخلاص.","لأن االله لم يجعلنا للغضب، بل لاقتناء الخلاص بربنا يسوع المسيح،","الذي مات لأجلنا، حتى إذا سهرنا أو نمنا نحيا جميعا معه.","لذلك عزوا بعضكم بعضا وابنوا أحدكم الآخر، كما تفعلون أيضا.","ثم نسألكم أيها الإخوة أن تعرفوا الذين يتعبون بينكم ويدبرونكم في الرب وينذرونكم،","وأن تعتبروهم كثيرا جدا في المحبة من أجل عملهم. سالموا بعضكم بعضا.","ونطلب إليكم أيها الإخوة: أنذروا الذين بلا ترتيب. شجعوا صغار النفوس، أسندوا الضعفاء. تأنوا على الجميع.","انظروا أن لا يجازي أحد أحدا عن شر بشر، بل كل حين اتبعوا الخير بعضكم لبعض وللجميع.","افرحوا كل حين.","صلوا بلا انقطاع.","اشكروا في كل شيء، لأن هذه هي مشيئة االله في المسيح يسوع من جهتكم.","لا تطفئوا الروح.","لا تحتقروا النبوات.","امتحنوا كل شيء. تمسكوا بالحسن.","امتنعوا عن كل شبه شر.","وإله السلام نفسه يقدسكم بالتمام. ولتحفظ روحكم ونفسكم وجسدكم كاملة بلا لوم عند مجيء ربنا يسوع المسيح.","أمين هو الذي يدعوكم الذي سيفعل أيضا.","أيها الإخوة صلوا لأجلنا.","سلموا على الإخوة جميعا بقبلة مقدسة.","أناشدكم بالرب أن تقرأ هذه الرسالة على جميع الإخوة القديسين.","نعمة ربنا يسوع المسيح معكم. آمين. رسالة بولس الرسول الثانية إلى أهل تسالونيكي"]];
BBD["تسالونيكي الثانية"]=[["بولس وسلوانس وتيموثاوس، إلى كنيسة التسالونيكيين، في االله أبينا والرب يسوع المسيح.","نعمة لكم وسلام من االله أبينا والرب يسوع المسيح.","ينبغي لنا أن نشكر االله كل حين من جهتكم أيها الإخوة كما يحق، لأن إيمانكم ينمو كثيرا، ومحبة كل واحد منكم جميعا بعضكم لبعض تزداد،","حتى إننا نحن أنفسنا نفتخر بكم في كنائس االله، من أجل صبركم وإيمانكم في جميع اضطهاداتكم والضيقات التي تحتملونها،","بينة على قضاء االله العادل، أنكم تؤهلون لملكوت االله الذي لأجله تتألمون أيضا،","إذ هو عادل عند االله أن الذين يضايقونكم يجازيهم ضيقا،","وإياكم الذين تتضايقون راحة معنا عند استعلان الرب يسوع من السماء مع ملائكة قوته،","في نار لهيب، معطيا نقمة للذين لا يعرفون االله والذين لا يطيعون إنجيل ربنا يسوع المسيح،","الذين سيعاقبون بهلاك أبدي من وجه الرب ومن مجد قوته،","متى جاء ليتمجد في قديسيه ويتعجب منه في جميع المؤمنين. لأن شهادتنا عندكم صدقت في ذلك اليوم،","الأمر الذي لأجله نصلي أيضا كل حين من جهتكم: أن يؤهلكم إلهنا للدعوة، ويكمل كل مسرة الصلاح وعمل الإيمان بقوة،","لكي يتمجد اسم ربنا يسوع المسيح فيكم، وأنتم فيه، بنعمة إلهنا والرب يسوع المسيح."],["ثم نسألكم أيها الإخوة من جهة مجيء ربنا يسوع المسيح واجتماعنا إليه،","أن لا تتزعزعوا سريعا عن ذهنكم، ولا ترتاعوا، لا بروح ولا بكلمة ولا برسالة كأنها منا: أي أن يوم المسيح قد حضر.","لا يخدعنكم أحد على طريقة ما، لأنه لا يأتي إن لم يأت الارتداد أولا، ويستعلن إنسان الخطية، ابن الهلاك،","المقاوم والمرتفع على كل ما يدعى إلها أو معبودا، حتى إنه يجلس في هيكل االله كإله مظهرا نفسه أنه إله.","أما تذكرون أني وأنا بعد عندكم كنت أقول لكم هذا؟","والآن تعلمون ما يحجز حتى يستعلن في وقته.","لأن سر الإثم الآن يعمل فقط، إلى أن يرفع من الوسط الذي يحجز الآن،","وحينئذ سيستعلن الأثيم، الذي الرب يبيده بنفخة فمه، ويبطله بظهور مجيئه.","الذي مجيئه بعمل الشيطان، بكل قوة، وبآيات وعجائب كاذبة،","وبكل خديعة الإثم، في الهالكين، لأنهم لم يقبلوا محبة الحق حتى يخلصوا.","ولأجل هذا سيرسل إليهم االله عمل الضلال، حتى يصدقوا الكذب،","لكي يدان جميع الذين لم يصدقوا الحق، بل سروا بالإثم.","وأما نحن فينبغي لنا أن نشكر االله كل حين لأجلكم أيها الإخوة المحبوبون من الرب، أن االله اختاركم من البدء للخلاص، بتقديس الروح وتصديق الحق.","الأمر الذي دعاكم إليه بإنجيلنا، لاقتناء مجد ربنا يسوع المسيح.","فاثبتوا إذا أيها الإخوة وتمسكوا بالتعاليم التي تعلمتموها، سواء كان بالكلام أم برسالتنا.","وربنا نفسه يسوع المسيح، واالله أبونا الذي أحبنا وأعطانا عزاء أبديا ورجاء صالحا بالنعمة،","يعزي قلوبكم ويثبتكم في كل كلام وعمل صالح."],["أخيرا أيها الإخوة صلوا لأجلنا، لكي تجري كلمة الرب وتتمجد، كما عندكم أيضا،","ولكي ننقذ من الناس الأردياء الأشرار. لأن الإيمان ليس للجميع.","أمين هو الرب الذي سيثبتكم ويحفظكم من الشرير.","ونثق بالرب من جهتكم أنكم تفعلون ما نوصيكم به وستفعلون أيضا.","والرب يهدي قلوبكم إلى محبة االله وإلى صبر المسيح.","ثم نوصيكم أيها الإخوة، باسم ربنا يسوع المسيح، أن تتجنبوا كل أخ يسلك بلا ترتيب، وليس حسب التعليم الذي أخذه منا.","إذ أنتم تعرفون كيف يجب أن يتمثل بنا، لأننا لم نسلك بلا ترتيب بينكم،","ولا أكلنا خبزا مجانا من أحد، بل كنا نشتغل بتعب وكد ليلا ونهارا، لكي لا نثقل على أحد منكم.","ليس أن لا سلطان لنا، بل لكي نعطيكم أنفسنا قدوة حتى تتمثلوا بنا.","فإننا أيضا حين كنا عندكم أوصيناكم بهذا: أنه إن كان أحد لا يريد أن يشتغل فلا يأكل أيضا.","لأننا نسمع أن قوما يسلكون بينكم بلا ترتيب، لا يشتغلون شيئا بل هم فضوليون.","فمثل هؤلاء نوصيهم ونعظهم بربنا يسوع المسيح أن يشتغلوا بهدوء، ويأكلوا خبز أنفسهم.","أما أنتم أيها الإخوة فلا تفشلوا في عمل الخير.","وإن كان أحد لا يطيع كلامنا بالرسالة، فسموا هذا ولا تخالطوه لكي يخجل،","ولكن لا تحسبوه كعدو، بل أنذروه كأخ.","ورب السلام نفسه يعطيكم السلام دائما من كل وجه. الرب مع جميعكم.","السلام بيدي أنا بولس، الذي هو علامة في كل رسالة. هكذا أنا أكتب.","نعمة ربنا يسوع المسيح مع جميعكم. آمين. رسالة بولس الرسول الأولى إلى تيموثاوس"]];
BBD["تيموثاوس الأولى"]=[["بولس، رسول يسوع المسيح، بحسب أمر االله مخلصنا وربنا يسوع المسيح، رجائنا.","إلى تيموثاوس، الابن الصريح في الإيمان. نعمة ورحمة وسلام من االله أبينا والمسيح يسوع ربنا.","كما طلبت إليك أن تمكث في أفسس، إذ كنت أنا ذاهبا إلى مكدونية، لكي توصي قوما أن لا يعلموا تعليما آخر،","ولا يصغوا إلى خرافات وأنساب لا حد لها، تسبب مباحثات دون بنيان االله الذي في الإيمان.","وأما غاية الوصية فهي المحبة من قلب طاهر، وضمير صالح، وإيمان بلا رياء.","الأمور التي إذ زاغ قوم عنها انحرفوا إلى كلام باطل.","يريدون أن يكونوا معلمي الناموس، وهم لا يفهمون ما يقولون ولا ما يقررونه.","ولكننا نعلم أن الناموس صالح، إن كان أحد يستعمله ناموسيا.","عالما هذا: أن الناموس لم يوضع للبار، بل للأثمة والمتمردين، للفجار والخطاة، للدنسين والمستبيحين، لقاتلي الآباء وقاتلي الأمهات، لقاتلي الناس،","للزناة، لمضاجعي الذكور، لسارقي الناس، للكذابين، للحانثين، وإن كان شيء آخر يقاوم التعليم الصحيح،","حسب إنجيل مجد االله المبارك الذي اؤتمنت أنا عليه.","وأنا أشكر المسيح يسوع ربنا الذي قواني، أنه حسبني أمينا، إذ جعلني للخدمة،","أنا الذي كنت قبلا مجدفا ومضطهدا ومفتريا. ولكنني رحمت، لأني فعلت بجهل في عدم إيمان.","وتفاضلت نعمة ربنا جدا مع الإيمان والمحبة التي في المسيح يسوع.","صادقة هي الكلمة ومستحقة كل قبول: أن المسيح يسوع جاء إلى العالم ليخلص الخطاة الذين أولهم أنا.","لكنني لهذا رحمت: ليظهر يسوع المسيح في أنا أولا كل أناة، مثالا للعتيدين أن يؤمنوا به للحياة الأبدية.","وملك الدهور الذي لا يفنى ولا يرى، الإله الحكيم وحده، له الكرامة والمجد إلى دهر الدهور. آمين.","هذه الوصية أيها الابن تيموثاوس أستودعك إياها حسب النبوات التي سبقت عليك، لكي تحارب فيها المحاربة الحسنة،","ولك إيمان وضمير صالح، الذي إذ رفضه قوم انكسرت بهم السفينة من جهة الإيمان أيضا،","الذين منهم هيمينايس والإسكندر، اللذان أسلمتهما للشيطان لكي يؤدبا حتى لا يجدفا."],["فأطلب أول كل شيء أن تقام طلبات وصلوات وابتهالات وتشكرات لأجل جميع الناس،","لأجل الملوك وجميع الذين هم في منصب، لكي نقضي حياة مطمئنة هادئة في كل تقوى ووقار،","لأن هذا حسن ومقبول لدى مخلصنا االله،","الذي يريد أن جميع الناس يخلصون وإلى معرفة الحق يقبلون.","لأنه يوجد إله واحد ووسيط واحد بين االله والناس: الإنسان يسوع المسيح،","الذي بذل نفسه فدية لأجل الجميع، الشهادة في أوقاتها الخاصة،","التي جعلت أنا لها كارزا ورسولا. الحق أقول في المسيح ولا أكذب، معلما للأمم في الإيمان والحق.","فأريد أن يصلي الرجال في كل مكان رافعين أيادي طاهرة، بدون غضب ولا جدال.","وكذلك أن النساء يزين ذواتهن بلباس الحشمة مع ورع وتعقل، لا بضفائر أو ذهب أو لآلئ أو ملابس كثيرة الثمن،","بل كما يليق بنساء متعاهدات بتقوى االله بأعمال صالحة.","لتتعلم المرأة بسكوت في كل خضوع.","ولكن لست آذن للمرأة أن تعلم ولا تتسلط على الرجل، بل تكون في سكوت،","لأن آدم جبل أولا ثم حواء،","وآدم لم يغو لكن المرأة أغويت فحصلت في التعدي،","ولكنها ستخلص بولادة الأولاد، إن ثبتن في الإيمان والمحبة والقداسة مع التعقل."],["صادقة هي الكلمة: إن ابتغى أحد الأسقفية فيشتهي عملا صالحا.","فيجب أن يكون الأسقف بلا لوم، بعل امرأة واحدة، صاحيا، عاقلا، محتشما، مضيفا للغرباء، صالحا للتعليم،","غير مدمن الخمر، ولا ضراب، ولا طامع بالربح القبيح، بل حليما، غير مخاصم، ولا محب للمال،","يدبر بيته حسنا، له أولاد في الخضوع بكل وقار.","وإنما إن كان أحد لا يعرف أن يدبر بيته، فكيف يعتني بكنيسة االله؟","غير حديث الإيمان لئلا يتصلف فيسقط في دينونة إبليس.","ويجب أيضا أن تكون له شهادة حسنة من الذين هم من خارج، لئلا يسقط في تعيير وفخ إبليس.","كذلك يجب أن يكون الشمامسة ذوي وقار، لا ذوي لسانين، غير مولعين بالخمر الكثير، ولا طامعين بالربح القبيح،","ولهم سر الإيمان بضمير طاهر.","وإنما هؤلاء أيضا ليختبروا أولا، ثم يتشمسوا إن كانوا بلا لوم.","كذلك يجب أن تكون النساء ذوات وقار، غير ثالبات، صاحيات، أمينات في كل شيء.","ليكن الشمامسة كل بعل امرأة واحدة، مدبرين أولادهم وبيوتهم حسنا،","لأن الذين تشمسوا حسنا يقتنون لأنفسهم درجة حسنة وثقة كثيرة في الإيمان الذي بالمسيح يسوع.","هذا أكتبه إليك راجيا أن آتي إليك عن قريب.","ولكن إن كنت أبطئ فلكي تعلم كيف يجب أن تتصرف في بيت االله، الذي هو كنيسة االله الحي، عمود الحق وقاعدته.","وبالإجماع عظيم هو سر التقوى: االله ظهر في الجسد، تبرر في الروح، تراءى لملائكة، كرز به بين الأمم، أومن به في العالم، رفع في المجد."],["ولكن الروح يقول صريحا: إنه في الأزمنة الأخيرة يرتد قوم عن الإيمان، تابعين أرواحا مضلة وتعاليم شياطين،","في رياء أقوال كاذبة، موسومة ضمائرهم،","مانعين عن الزواج، وآمرين أن يمتنع عن أطعمة قد خلقها االله لتتناول بالشكر من المؤمنين وعارفي الحق.","لأن كل خليقة االله جيدة، ولا يرفض شيء إذا أخذ مع الشكر،","لأنه يقدس بكلمة االله والصلاة.","إن فكرت الإخوة بهذا تكون خادما صالحا ليسوع المسيح، متربيا بكلام الإيمان والتعليم الحسن الذي تتبعته.","وأما الخرافات الدنسة العجائزية فارفضها، وروض نفسك للتقوى.","لأن الرياضة الجسدية نافعة لقليل، ولكن التقوى نافعة لكل شيء، إذ لها موعد الحياة الحاضرة والعتيدة.","صادقة هي الكلمة ومستحقة كل قبول.","لأننا لهذا نتعب ونعير، لأننا قد ألقينا رجاءنا على االله الحي، الذي هو مخلص جميع الناس ولا سيما المؤمنين.","أوص بهذا وعلم.","لا يستهن أحد بحداثتك، بل كن قدوة للمؤمنين في الكلام، في التصرف، في المحبة، في الروح، في الإيمان، في الطهارة.","إلى أن أجيء اعكف على القراءة والوعظ والتعليم.","لا تهمل الموهبة التي فيك المعطاة لك بالنبوة مع وضع أيدي المشيخة.","اهتم بهذا. كن فيه، لكي يكون تقدمك ظاهرا في كل شيء.","لاحظ نفسك والتعليم وداوم على ذلك، لأنك إذا فعلت هذا تخلص نفسك والذين يسمعونك أيضا."],["لا تزجر شيخا بل عظه كأب، والأحداث كإخوة،","والعجائز كأمهات، والحدثات كأخوات، بكل طهارة.","أكرم الأرامل اللواتي هن بالحقيقة أرامل.","ولكن إن كانت أرملة لها أولاد أو حفدة، فليتعلموا أولا أن يوقروا أهل بيتهم ويوفوا والديهم المكافأة، لأن هذا صالح ومقبول أمام االله.","ولكن التي هي بالحقيقة أرملة ووحيدة، فقد ألقت رجاءها على االله، وهي تواظب على الطلبات والصلوات ليلا ونهارا.","وأما المتنعمة فقد ماتت وهي حية.","فأوص بهذا لكي يكن بلا لوم.","وإن كان أحد لا يعتني بخاصته، ولا سيما أهل بيته، فقد أنكر الإيمان، وهو شر من غير المؤمن.","لتكتتب أرملة إن لم يكن عمرها أقل من ستين سنة، امرأة رجل واحد،","مشهودا لها في أعمال صالحة، إن تكن قد ربت الأولاد، أضافت الغرباء، غسلت أرجل القديسين، ساعدت المتضايقين، اتبعت كل عمل صالح.","أما الأرامل الحدثات فارفضهن، لأنهن متى بطرن على المسيح يردن أن يتزوجن،","ولهن دينونة لأنهن رفضن الإيمان الأول.","ومع ذلك أيضا يتعلمن أن يكن بطالات، يطفن في البيوت. ولسن بطالات فقط بل مهذارات أيضا، وفضوليات، يتكلمن بما لا يجب.","فأريد أن الحدثات يتزوجن ويلدن الأولاد ويدبرن البيوت، ولا يعطين علة للمقاوم من أجل الشتم.","فإن بعضهن قد انحرفن وراء الشيطان.","إن كان لمؤمن أو مؤمنة أرامل فليساعدهن ولا يثقل على الكنيسة، لكي تساعد هي اللواتي هن بالحقيقة أرامل.","أما الشيوخ المدبرون حسنا فليحسبوا أهلا لكرامة مضاعفة، ولا سيما الذين يتعبون في الكلمة والتعليم،","لأن الكتاب يقول: »لا تكم ثورا دارسا، والفاعل مستحق أجرته«.","لا تقبل شكاية على شيخ إلا على شاهدين أو ثلاثة شهود.","الذين يخطئون وبخهم أمام الجميع لكي يكون عند الباقين خوف.","أناشدك أمام االله والرب يسوع المسيح والملائكة المختارين أن تحفظ هذا بدون غرض، ولا تعمل شيئا بمحاباة.","لا تضع يدا على أحد بالعجلة، ولا تشترك في خطايا الآخرين. احفظ نفسك طاهرا.","لا تكن في ما بعد شراب ماء، بل استعمل خمرا قليلا من أجل معدتك وأسقامك الكثيرة.","خطايا بعض الناس واضحة تتقدم إلى القضاء، وأما البعض فتتبعهم.","كذلك أيضا الأعمال الصالحة واضحة، والتي هي خلاف ذلك لا يمكن أن تخفى."],["جميع الذين هم عبيد تحت نير فليحسبوا سادتهم مستحقين كل إكرام، لئلا يفترى على اسم االله وتعليمه.","والذين لهم سادة مؤمنون لا يستهينوا بهم لأنهم إخوة، بل ليخدموهم أكثر، لأن الذين يتشاركون في الفائدة هم مؤمنون ومحبوبون. علم وعظ بهذا.","إن كان أحد يعلم تعليما آخر، ولا يوافق كلمات ربنا يسوع المسيح الصحيحة، والتعليم الذي هو حسب التقوى","فقد تصلف، وهو لا يفهم شيئا، بل هو متعلل بمباحثات ومماحكات الكلام التي منها يحصل الحسد والخصام والافتراء والظنون الردية،","ومنازعات أناس فاسدي الذهن وعادمي الحق، يظنون أن التقوى تجارة. تجنب مثل هؤلاء.","وأما التقوى مع القناعة فهي تجارة عظيمة،","لأننا لم ندخل العالم بشيء، وواضح أننا لا نقدر أن نخرج منه بشيء.","فإن كان لنا قوت وكسوة فلنكتف بهما.","وأما الذين يريدون أن يكونوا أغنياء فيسقطون في تجربة وفخ وشهوات كثيرة غبية ومضرة تغرق الناس في العطب والهلاك،","لأن محبة المال أصل لكل الشرور، الذي إذ ابتغاه قوم ضلوا عن الإيمان، وطعنوا أنفسهم بأوجاع كثيرة.","وأما أنت يا إنسان االله فاهرب من هذا، واتبع البر والتقوى والإيمان والمحبة والصبر والوداعة.","جاهد جهاد الإيمان الحسن، وأمسك بالحياة الأبدية التي إليها دعيت أيضا، واعترفت الاعتراف الحسن أمام شهود كثيرين.","أوصيك أمام االله الذي يحيي الكل والمسيح يسوع الذي شهد لدى بيلاطس البنطي بالاعتراف الحسن:","أن تحفظ الوصية بلا دنس ولا لوم إلى ظهور ربنا يسوع المسيح،","الذي سيبينه في أوقاته المبارك العزيز الوحيد، ملك الملوك ورب الأرباب،","الذي وحده له عدم الموت، ساكنا في نور لا يدنى منه، الذي لم يره أحد من الناس ولا يقدر أن يراه، الذي له الكرامة والقدرة الأبدية. آمين.","أوص الأغنياء في الدهر الحاضر أن لا يستكبروا، ولا يلقوا رجاءهم على غير يقينية الغنى، بل على االله الحي الذي يمنحنا كل شيء بغنى للتمتع.","وأن يصنعوا صلاحا، وأن يكونوا أغنياء في أعمال صالحة، وأن يكونوا أسخياء في العطاء كرماء في التوزيع،","مدخرين لأنفسهم أساسا حسنا للمستقبل، لكي يمسكوا بالحياة الأبدية.","يا تيموثاوس، احفظ الوديعة، معرضا عن الكلام الباطل الدنس، ومخالفات العلم الكاذب الاسم،","الذي إذ تظاهر به قوم زاغوا من جهة الإيمان.","النعمة معك. آمين. رسالة بولس الرسول الثانية إلى تيموثاوس"]];
BBD["تيموثاوس الثانية"]=[["بولس، رسول يسوع المسيح بمشيئة االله، لأجل وعد الحياة التي في يسوع المسيح.","إلى تيموثاوس الابن الحبيب. نعمة ورحمة وسلام من االله الآب والمسيح يسوع ربنا.","إني أشكر االله الذي أعبده من أجدادي بضمير طاهر، كما أذكرك بلا انقطاع في طلباتي ليلا ونهارا،","مشتاقا أن أراك، ذاكرا دموعك لكي أمتلئ فرحا،","إذ أتذكر الإيمان العديم الرياء الذي فيك، الذي سكن أولا في جدتك لوئيس وأمك أفنيكي، ولكني موقن أنه فيك أيضا.","فلهذا السبب أذكرك أن تضرم أيضا موهبة االله التي فيك بوضع يدي،","لأن االله لم يعطنا روح الفشل، بل روح القوة والمحبة والنصح.","فلا تخجل بشهادة ربنا، ولا بي أنا أسيره، بل اشترك في احتمال المشقات لأجل الإنجيل بحسب قوة االله،","الذي خلصنا ودعانا دعوة مقدسة، لا بمقتضى أعمالنا، بل بمقتضى القصد والنعمة التي أعطيت لنا في المسيح يسوع قبل الأزمنة الأزلية،","وإنما أظهرت الآن بظهور مخلصنا يسوع المسيح، الذي أبطل الموت وأنار الحياة والخلود بواسطة الإنجيل.","الذي جعلت أنا له كارزا ورسولا ومعلما للأمم.","لهذا السبب أحتمل هذه الأمور أيضا. لكنني لست أخجل، لأنني عالم بمن آمنت، وموقن أنه قادر أن يحفظ وديعتي إلى ذلك اليوم.","تمسك بصورة الكلام الصحيح الذي سمعته مني، في الإيمان وٱلمحبة التي في المسيح يسوع.","احفظ الوديعة الصالحة بالروح القدس الساكن فينا.","أنت تعلم هذا أن جميع الذين في أسيا ارتدوا عني، الذين منهم فيجلس وهرموجانس.","ليعط الرب رحمة لبيت أنيسيفورس، لأنه مرارا كثيرة أراحني ولم يخجل بسلسلتي،","بل لما كان في رومية طلبني بأوفر اجتهاد فوجدني.","ليعطه الرب أن يجد رحمة من الرب في ذلك اليوم. وكل ما كان يخدم في أفسس أنت تعرفه جيدا."],["فتقو أنت يا ابني بالنعمة التي في المسيح يسوع.","وما سمعته مني بشهود كثيرين، أودعه أناسا أمناء، يكونون أكفاء أن يعلموا آخرين أيضا.","فاشترك أنت في احتمال المشقات كجندي صالح ليسوع المسيح.","ليس أحد وهو يتجند يرتبك بأعمال الحياة لكي يرضي من جنده،","وأيضا إن كان أحد يجاهد لا يكلل إن لم يجاهد قانونيا.","يجب أن الحراث الذي يتعب يشترك هو أولا في الأثمار.","افهم ما أقول. فليعطك الرب فهما في كل شيء.","اذكر يسوع المسيح المقام من الأموات من نسل داود بحسب إنجيلي،","الذي فيه أحتمل المشقات حتى القيود كمذنب. لكن كلمة االله لا تقيد.","لأجل ذلك أنا أصبر على كل شيء لأجل المختارين، لكي يحصلوا هم أيضا على الخلاص الذي في المسيح يسوع مع مجد أبدي.","صادقة هي الكلمة: أنه إن كنا قد متنا معه فسنحيا أيضا معه.","إن كنا نصبر فسنملك أيضا معه. إن كنا ننكره فهو أيضا سينكرنا.","إن كنا غير أمناء فهو يبقى أمينا، لن يقدر أن ينكر نفسه.","فكر بهذه الأمور مناشدا قدام الرب أن لا يتماحكوا بالكلام، الأمر غير النافع لشيء، لهدم السامعين.","اجتهد أن تقيم نفسك الله مزكى، عاملا لا يخزى، مفصلا كلمة الحق بالاستقامة.","وأما الأقوال الباطلة الدنسة فاجتنبها، لأنهم يتقدمون إلى أكثر فجور،","وكلمتهم ترعى كآكلة، الذين منهم هيمينايس وفيليتس،","اللذان زاغا عن الحق، قائلين: »إن القيامة قد صارت« فيقلبان إيمان قوم.","ولكن أساس االله الراسخ قد ثبت، إذ له هذا الختم. يعلم الرب الذين هم له. وليتجنب الإثم كل من يسمي اسم المسيح.","ولكن في بيت كبير ليس آنية من ذهب وفضة فقط، بل من خشب وخزف أيضا، وتلك للكرامة وهذه للهوان.","فإن طهر أحد نفسه من هذه يكون إناء للكرامة، مقدسا، نافعا للسيد، مستعدا لكل عمل صالح.","أما الشهوات الشبابية فاهرب منها، واتبع البر والإيمان والمحبة والسلام مع الذين يدعون الرب من قلب نقي.","والمباحثات الغبية والسخيفة اجتنبها، عالما أنها تولد خصومات،","وعبد الرب لا يجب أن يخاصم، بل يكون مترفقا بالجميع، صالحا للتعليم، صبورا على المشقات،","مؤدبا بالوداعة المقاومين، عسى أن يعطيهم االله توبة لمعرفة الحق،","فيستفيقوا من فخ إبليس إذ قد اقتنصهم لإرادته."],["ولكن اعلم هذا أنه في الأيام الأخيرة ستأتي أزمنة صعبة،","لأن الناس يكونون محبين لأنفسهم، محبين للمال، متعظمين، مستكبرين، مجدفين، غير طائعين لوالديهم، غير شاكرين، دنسين،","بلا حنو، بلا رضى، ثالبين، عديمي النزاهة، شرسين، غير محبين للصلاح،","خائنين، مقتحمين، متصلفين، محبين للذات دون محبة لله،","لهم صورة التقوى ولكنهم منكرون قوتها. فأعرض عن هؤلاء.","فإنه من هؤلاء هم الذين يدخلون البيوت، ويسبون نسيات محملات خطايا، منساقات بشهوات مختلفة.","يتعلمن في كل حين، ولا يستطعن أن يقبلن إلى معرفة الحق أبدا.","وكما قاوم ينيس ويمبريس موسى، كذلك هؤلاء أيضا يقاومون الحق. أناس فاسدة أذهانهم، ومن جهة الإيمان مرفوضون.","لكنهم لا يتقدمون أكثر، لأن حمقهم سيكون واضحا للجميع، كما كان حمق ذينك أيضا.","وأما أنت فقد تبعت تعليمي، وسيرتي، وقصدي، وإيماني، وأناتي، ومحبتي، وصبري،","واضطهاداتي، وآلامي، مثل ما أصابني في أنطاكية وإيقونية ولسترة. أية اضطهادات احتملت! ومن الجميع أنقذني الرب.","وجميع الذين يريدون أن يعيشوا بالتقوى في المسيح يسوع يضطهدون.","ولكن الناس الأشرار المزورين سيتقدمون إلى أردأ، مضلين ومضلين.","وأما أنت فاثبت على ما تعلمت وأيقنت، عارفا ممن تعلمت.","وأنك منذ الطفولية تعرف الكتب المقدسة، القادرة أن تحكمك للخلاص، بالإيمان الذي في المسيح يسوع.","كل الكتاب هو موحى به من االله، ونافع للتعليم والتوبيخ، للتقويم والتأديب الذي في البر،","لكي يكون إنسان االله كاملا، متأهبا لكل عمل صالح."],["أنا أناشدك إذا أمام االله والرب يسوع المسيح، العتيد أن يدين الأحياء والأموات، عند ظهوره وملكوته:","اكرز بالكلمة. اعكف على ذلك في وقت مناسب وغير مناسب. وبخ، انتهر، عظ بكل أناة وتعليم.","لأنه سيكون وقت لا يحتملون فيه التعليم الصحيح، بل حسب شهواتهم الخاصة يجمعون لهم معلمين مستحكة مسامعهم،","فيصرفون مسامعهم عن الحق، وينحرفون إلى الخرافات.","وأما أنت فاصح في كل شيء. احتمل المشقات. اعمل عمل المبشر. تمم خدمتك.","فإني أنا الآن أسكب سكيبا، ووقت انحلالي قد حضر.","قد جاهدت الجهاد الحسن، أكملت السعي، حفظت الإيمان،","وأخيرا قد وضع لي إكليل البر، الذي يهبه لي في ذلك اليوم الرب الديان العادل، وليس لي فقط، بل لجميع الذين يحبون ظهوره أيضا.","بادر أن تجيء إلي سريعا،","لأن ديماس قد تركني إذ أحب العالم الحاضر وذهب إلى تسالونيكي، وكريسكيس إلى غلاطية، وتيطس إلى دلماطية.","لوقا وحده معي. خذ مرقس وأحضره معك لأنه نافع لي للخدمة.","أما تيخيكس فقد أرسلته إلى أفسس.","الرداء الذي تركته في ترواس عند كاربس أحضره متى جئت، والكتب أيضا ولا سيما الرقوق.","إسكندر النحاس أظهر لي شرورا كثيرة. ليجازه الرب حسب أعماله.","فاحتفظ منه أنت أيضا لأنه قاوم أقوالنا جدا.","في احتجاجي الأول لم يحضر أحد معي، بل الجميع تركوني. لا يحسب عليهم.","ولكن الرب وقف معي وقواني، لكي تتم بي الكرازة، ويسمع جميع الأمم، فأنقذت من فم الأسد.","وسينقذني الرب من كل عمل رديء ويخلصني لملكوته السماوي. الذي له المجد إلى دهر الدهور. آمين.","سلم على فرسكا وأكيلا وبيت أنيسيفورس.","أراستس بقي في كورنثوس. وأما تروفيمس فتركته في ميليتس مريضا.","بادر أن تجيء قبل الشتاء. يسلم عليك أفبولس وبوديس ولينس وكلافدية والإخوة جميعا.","الرب يسوع المسيح مع روحك. النعمة معكم. آمين. رسالة بولس الرسول إلى تيطس"]];
BBD["تيطس"]=[["بولس، عبد االله، ورسول يسوع المسيح، لأجل إيمان مختاري االله ومعرفة الحق، الذي هو حسب التقوى،","على رجاء الحياة الأبدية، التي وعد بها االله المنزه عن الكذب، قبل الأزمنة الأزلية،","وإنما أظهر كلمته في أوقاتها الخاصة، بالكرازة التي اؤتمنت أنا عليها، بحسب أمر مخلصنا االله،","إلى تيطس، الابن الصريح حسب الإيمان المشترك. نعمة ورحمة وسلام من االله الآب والرب يسوع المسيح مخلصنا.","من أجل هذا تركتك في كريت لكي تكمل ترتيب الأمور الناقصة، وتقيم في كل مدينة شيوخا كما أوصيتك.","إن كان أحد بلا لوم، بعل امرأة واحدة، له أولاد مؤمنون ليسوا في شكاية الخلاعة ولا متمردين -","لأنه يجب أن يكون الأسقف بلا لوم كوكيل االله، غير معجب بنفسه، ولا غضوب، ولا مدمن الخمر، ولا ضراب، ولا طامع في الربح القبيح،","بل مضيفا للغرباء، محبا للخير، متعقلا، بارا، ورعا، ضابطا لنفسه،","ملازما للكلمة الصادقة التي بحسب التعليم، لكي يكون قادرا أن يعظ بالتعليم الصحيح ويوبخ المناقضين.","فإنه يوجد كثيرون متمردين يتكلمون بالباطل، ويخدعون العقول، ولا سيما الذين من الختان -","الذين يجب سد أفواههم، فإنهم يقلبون بيوتا بجملتها، معلمين ما لا يجب، من أجل الربح القبيح.","قال واحد منهم - وهو نبي لهم خاص: »الكريتيون دائما كذابون. وحوش ردية. بطون بطالة«.","هذه الشهادة صادقة. فلهذا السبب وبخهم بصرامة لكي يكونوا أصحاء في الإيمان،","لا يصغون إلى خرافات يهودية ووصايا أناس مرتدين عن الحق.","كل شيء طاهر للطاهرين، وأما للنجسين وغير المؤمنين فليس شيء طاهرا، بل قد تنجس ذهنهم أيضا وضميرهم.","يعترفون بأنهم يعرفون االله، ولكنهم بالأعمال ينكرونه، إذ هم رجسون غير طائعين، ومن جهة كل عمل صالح مرفوضون."],["وأما أنت فتكلم بما يليق بالتعليم الصحيح:","أن يكون الأشياخ صاحين، ذوي وقار، متعقلين، أصحاء في الإيمان والمحبة والصبر.","كذلك العجائز في سيرة تليق بالقداسة، غير ثالبات، غير مستعبدات للخمر الكثير، معلمات الصلاح،","لكي ينصحن الحدثات أن يكن محبات لرجالهن ويحببن أولادهن،","متعقلات، عفيفات، ملازمات بيوتهن، صالحات، خاضعات لرجالهن، لكي لا يجدف على كلمة االله.","كذلك عظ الأحداث أن يكونوا متعقلين،","مقدما نفسك في كل شيء قدوة للأعمال الحسنة، ومقدما في التعليم نقاوة، ووقارا، وإخلاصا،","وكلاما صحيحا غير ملوم، لكي يخزى المضاد، إذ ليس له شيء رديء يقوله عنكم.","والعبيد أن يخضعوا لسادتهم، ويرضوهم في كل شيء، غير مناقضين،","غير مختلسين، بل مقدمين كل أمانة صالحة، لكي يزينوا تعليم مخلصنا االله في كل شيء.","لأنه قد ظهرت نعمة االله المخلصة لجميع الناس،","معلمة إيانا أن ننكر الفجور والشهوات العالمية، ونعيش بالتعقل والبر والتقوى في العالم الحاضر،","منتظرين الرجاء المبارك وظهور مجد االله العظيم ومخلصنا يسوع المسيح،","الذي بذل نفسه لأجلنا، لكي يفدينا من كل إثم، ويطهر لنفسه شعبا خاصا غيورا في أعمال حسنة.","تكلم بهذه وعظ ووبخ بكل سلطان. لا يستهن بك أحد."],["ذكرهم أن يخضعوا للرياسات والسلاطين ويطيعوا، ويكونوا مستعدين لكل عمل صالح،","ولا يطعنوا في أحد، ويكونوا غير مخاصمين، حلماء، مظهرين كل وداعة لجميع الناس.","لأننا كنا نحن أيضا قبلا أغبياء، غير طائعين، ضالين، مستعبدين لشهوات ولذات مختلفة، عائشين في الخبث والحسد، ممقوتين، مبغضين بعضنا بعضا.","ولكن حين ظهر لطف مخلصنا االله وإحسانه -","لا بأعمال في بر عملناها نحن، بل بمقتضى رحمته -خلصنا بغسل الميلاد الثاني وتجديد الروح القدس،","الذي سكبه بغنى علينا بيسوع المسيح مخلصنا.","حتى إذا تبررنا بنعمته نصير ورثة حسب رجاء الحياة الأبدية.","صادقة هي الكلمة. وأريد أن تقرر هذه الأمور، لكي يهتم الذين آمنوا باالله أن يمارسوا أعمالا حسنة. فإن هذه الأمور هي الحسنة والنافعة للناس.","وأما المباحثات الغبية والأنساب والخصومات والمنازعات الناموسية فاجتنبها، لأنها غير نافعة، وباطلة.","الرجل المبتدع بعد الإنذار مرة ومرتين أعرض عنه.","عالما أن مثل هذا قد انحرف، وهو يخطئ محكوما عليه من نفسه.","حينما أرسل إليك أرتيماس أو تيخيكس بادر أن تأتي إلي إلى نيكوبوليس، لأني عزمت أن أشتي هناك.","جهز زيناس الناموسي وأبلوس باجتهاد للسفر حتى لا يعوزهما شيء.","وليتعلم من لنا أيضا أن يمارسوا أعمالا حسنة للحاجات الضرورية، حتى لا يكونوا بلا ثمر.","يسلم عليك الذين معي جميعا. سلم على الذين يحبوننا في الإيمان. النعمة مع جميعكم. آمين."]];
BBD["فليمون"]=[["بولس، أسير يسوع المسيح، وتيموثاوس الأخ: إلى فليمون المحبوب والعامل معنا،","وإلى أبفية المحبوبة، وأرخبس المتجند معنا، وإلى الكنيسة التي في بيتك.","نعمة لكم وسلام من االله أبينا والرب يسوع المسيح.","أشكر إلهي كل حين ذاكرا إياك في صلواتي،","سامعا بمحبتك، والإيمان الذي لك نحو الرب يسوع ولجميع القديسين،","لكي تكون شركة إيمانك فعالة في معرفة كل الصلاح الذي فيكم لأجل المسيح يسوع.","لأن لنا فرحا كثيرا وتعزية بسبب محبتك، لأن أحشاء القديسين قد استراحت بك أيها الأخ.","لذلك، وإن كان لي بالمسيح ثقة كثيرة أن آمرك بما يليق،","من أجل المحبة، أطلب بالحري إذ أنا إنسان هكذا نظير بولس الشيخ، والآن أسير يسوع المسيح أيضا -","أطلب إليك لأجل ابني أنسيمس، الذي ولدته في قيودي،","الذي كان قبلا غير نافع لك، ولكنه الآن نافع لك ولي،","الذي رددته. فاقبله، الذي هو أحشائي.","الذي كنت أشاء أن أمسكه عندي لكي يخدمني عوضا عنك في قيود الإنجيل -","ولكن بدون رأيك لم أرد أن أفعل شيئا، لكي لا يكون خيرك كأنه على سبيل الاضطرار بل على سبيل الاختيار.","لأنه ربما لأجل هذا افترق عنك إلى ساعة، لكي يكون لك إلى الأبد،","لا كعبد في ما بعد، بل أفضل من عبد: أخا محبوبا، ولا سيما إلي. فكم بالحري إليك في الجسد والرب جميعا!","فإن كنت تحسبني شريكا فاقبله نظيري.","ثم إن كان قد ظلمك بشيء، أو لك عليه دين، فاحسب ذلك علي.","أنا بولس كتبت بيدي. أنا أوفي. حتى لا أقول لك إنك مديون لي بنفسك أيضا.","نعم أيها الأخ، ليكن لي فرح بك في الرب. أرح أحشائي في الرب.","إذ أنا واثق بإطاعتك كتبت إليك، عالما أنك تفعل أيضا أكثر مما أقول.","ومع هذا أعدد لي أيضا منزلا، لأني أرجو أنني بصلواتكم سأوهب لكم.","يسلم عليك أبفراس المأسور معي في المسيح يسوع،","ومرقس، وأرسترخس، وديماس، ولوقا العاملون معي.","نعمة ربنا يسوع المسيح مع روحكم. آمين. )إلى فليمون، كتبت من رومية، على يد أنسيمس الخادم( الرسالة إلى العبرانيين"]];
BBD["العبرانيين"]=[["االله، بعد ما كلم الآباء بالأنبياء قديما، بأنواع وطرق كثيرة،","كلمنا في هذه الأيام الأخيرة في ابنه - الذي جعله وارثا لكل شيء، الذي به أيضا عمل العالمين.","الذي، وهو بهاء مجده، ورسم جوهره، وحامل كل الأشياء بكلمة قدرته، بعد ما صنع بنفسه تطهيرا لخطايانا، جلس في يمين العظمة في الأعالي،","صائرا أعظم من الملائكة بمقدار ما ورث اسما أفضل منهم.","لأنه لمن من الملائكة قال قط: »أنت ابني أنا اليوم ولدتك«؟ وأيضا: »أنا أكون له أبا وهو يكون لي ابنا«؟","وأيضا متى أدخل البكر إلى العالم يقول: »ولتسجد له كل ملائكة االله«.","وعن الملائكة يقول: »الصانع ملائكته رياحا وخدامه لهيب نار«.","وأما عن الابن: »كرسيك يا أالله إلى دهر الدهور. قضيب استقامة قضيب ملكك.","أحببت البر وأبغضت الإثم. من أجل ذلك مسحك االله إلهك بزيت الابتهاج أكثر من شركائك«.","و»أنت يا رب في البدء أسست الأرض، والسماوات هي عمل يديك.","هي تبيد ولكن أنت تبقى، وكلها كثوب تبلى،","وكرداء تطويها فتتغير. ولكن أنت أنت، وسنوك لن تفنى«.","ثم لمن من الملائكة قال قط: »اجلس عن يميني حتى أضع أعداءك موطئا لقدميك؟«","أليس جميعهم أرواحا خادمة مرسلة للخدمة لأجل العتيدين أن يرثوا الخلاص!"],["لذلك يجب أن نتنبه أكثر إلى ما سمعنا لئلا نفوته،","لأنه إن كانت الكلمة التي تكلم بها ملائكة قد صارت ثابتة، وكل تعد ومعصية نال مجازاة عادلة،","فكيف ننجو نحن إن أهملنا خلاصا هذا مقداره، قد ابتدأ الرب بالتكلم به، ثم تثبت لنا من الذين سمعوا،","شاهدا االله معهم بآيات وعجائب وقوات متنوعة ومواهب الروح القدس، حسب إرادته؟","فإنه لملائكة لم يخضع »العالم العتيد« الذي نتكلم عنه.","لكن شهد واحد في موضع قائلا: »ما هو الإنسان حتى تذكره، أو ابن الإنسان حتى تفتقده؟","وضعته قليلا عن الملائكة. بمجد وكرامة كللته، وأقمته على أعمال يديك.","أخضعت كل شيء تحت قدميه«. لأنه إذ أخضع الكل له لم يترك شيئا غير خاضع له - على أننا الآن لسنا نرى الكل بعد مخضعا له -","ولكن الذي وضع قليلا عن الملائكة، يسوع، نراه مكللا بالمجد والكرامة، من أجل ألم الموت، لكي يذوق بنعمة االله الموت لأجل كل واحد.","لأنه لاق بذاك الذي من أجله الكل وبه الكل، وهو آت بأبناء كثيرين إلى المجد أن يكمل رئيس خلاصهم بالآلام.","لأن المقدس والمقدسين جميعهم من واحد، فلهذا السبب لا يستحي أن يدعوهم إخوة،","قائلا: »أخبر باسمك إخوتي، وفي وسط الكنيسة أسبحك«.","وأيضا: »أنا أكون متوكلا عليه«. وأيضا: »ها أنا والأولاد الذين أعطانيهم االله«.","فإذ قد تشارك الأولاد في اللحم والدم اشترك هو أيضا كذلك فيهما، لكي يبيد بالموت ذاك الذي له سلطان الموت، أي إبليس،","ويعتق أولئك الذين خوفا من الموت كانوا جميعا كل حياتهم تحت العبودية.","لأنه حقا ليس يمسك الملائكة، بل يمسك نسل إبراهيم.","من ثم كان ينبغي أن يشبه إخوته في كل شيء، لكي يكون رحيما، ورئيس كهنة أمينا في ما لله حتى يكفر خطايا الشعب.","لأنه في ما هو قد تألم مجربا يقدر أن يعين المجربين."],["من ثم أيها الإخوة القديسون، شركاء الدعوة السماوية، لاحظوا رسول اعترافنا ورئيس كهنته المسيح يسوع،","حال كونه أمينا للذي أقامه، كما كان موسى أيضا في كل بيته.","فإن هذا قد حسب أهلا لمجد أكثر من موسى، بمقدار ما لباني البيت من كرامة أكثر من البيت.","لأن كل بيت يبنيه إنسان ما، ولكن باني الكل هو االله.","وموسى كان أمينا في كل بيته كخادم، شهادة للعتيد أن يتكلم به.","وأما المسيح فكابن على بيته. وبيته نحن إن تمسكنا بثقة الرجاء وافتخاره ثابتة إلى النهاية.","لذلك كما يقول الروح القدس: »اليوم إن سمعتم صوته","فلا تقسوا قلوبكم، كما في الإسخاط، يوم التجربة في القفر","حيث جربني آباؤكم. اختبروني وأبصروا أعمالي أربعين سنة.","لذلك مقت ذلك الجيل، وقلت إنهم دائما يضلون في قلوبهم، ولكنهم لم يعرفوا سبلي.","حتى أقسمت في غضبي لن يدخلوا راحتي«.","انظروا أيها الإخوة أن لا يكون في أحدكم قلب شرير بعدم إيمان في الارتداد عن االله الحي،","بل عظوا أنفسكم كل يوم، ما دام الوقت يدعى اليوم، لكي لا يقسى أحد منكم بغرور الخطية.","لأننا قد صرنا شركاء المسيح، إن تمسكنا ببداءة الثقة ثابتة إلى النهاية،","إذ قيل: »اليوم إن سمعتم صوته فلا تقسوا قلوبكم، كما في الإسخاط«.","فمن هم الذين إذ سمعوا أسخطوا؟ أليس جميع الذين خرجوا من مصر بواسطة موسى؟","ومن مقت أربعين سنة؟ أليس الذين أخطأوا، الذين جثثهم سقطت في القفر؟","ولمن أقسم لن يدخلوا راحته، إلا للذين لم يطيعوا؟","فنرى أنهم لم يقدروا أن يدخلوا لعدم الإيمان."],["فلنخف، أنه مع بقاء وعد بالدخول إلى راحته، يرى أحد منكم أنه قد خاب منه!","لأننا نحن أيضا قد بشرنا كما أولئك، لكن لم تنفع كلمة الخبر أولئك. إذ لم تكن ممتزجة بالإيمان في الذين سمعوا.","لأننا نحن المؤمنين ندخل الراحة، كما قال: »حتى أقسمت في غضبي لن يدخلوا راحتي!« مع كون الأعمال قد أكملت منذ تأسيس العالم.","لأنه قال في موضع عن السابع: »واستراح االله في اليوم السابع من جميع أعماله«.","وفي هذا أيضا: »لن يدخلوا راحتي«.","فإذ بقي أن قوما يدخلونها، والذين بشروا أولا لم يدخلوا لسبب العصيان،","يعين أيضا يوما قائلا في داود: »اليوم« بعد زمان هذا مقداره، كما قيل: »اليوم إن سمعتم صوته فلا تقسوا قلوبكم«.","لأنه لو كان يشوع قد أراحهم لما تكلم بعد ذلك عن يوم آخر.","إذا بقيت راحة لشعب االله!","لأن الذي دخل راحته استراح هو أيضا من أعماله، كما االله من أعماله.","فلنجتهد أن ندخل تلك الراحة، لئلا يسقط أحد في عبرة العصيان هذه عينها.","لأن كلمة االله حية وفعالة وأمضى من كل سيف ذي حدين، وخارقة إلى مفرق النفس والروح والمفاصل والمخاخ، ومميزة أفكار القلب ونياته.","وليست خليقة غير ظاهرة قدامه، بل كل شيء عريان ومكشوف لعيني ذلك الذي معه أمرنا.","فإذ لنا رئيس كهنة عظيم قد اجتاز السماوات، يسوع ابن االله، فلنتمسك بالإقرار.","لأن ليس لنا رئيس كهنة غير قادر أن يرثي لضعفاتنا، بل مجرب في كل شيء مثلنا، بلا خطية.","فلنتقدم بثقة إلى عرش النعمة لكي ننال رحمة ونجد نعمة عونا في حينه."],["لأن كل رئيس كهنة مأخوذ من الناس يقام لأجل الناس في ما لله، لكي يقدم قرابين وذبائح عن الخطايا،","قادرا أن يترفق بالجهال والضالين، إذ هو أيضا محاط بالضعف.","ولهذا الضعف يلتزم أنه كما يقدم عن الخطايا لأجل الشعب هكذا أيضا لأجل نفسه.","ولا يأخذ أحد هذه الوظيفة بنفسه، بل المدعو من االله، كما هارون أيضا.","كذلك المسيح أيضا لم يمجد نفسه ليصير رئيس كهنة، بل الذي قال له: »أنت ابني أنا اليوم ولدتك«.","كما يقول أيضا في موضع آخر: »أنت كاهن إلى الأبد على رتبة ملكي صادق«.","الذي، في أيام جسده، إذ قدم بصراخ شديد ودموع طلبات وتضرعات للقادر أن يخلصه من الموت، وسمع له من أجل تقواه،","مع كونه ابنا تعلم الطاعة مما تألم به.","وإذ كمل صار لجميع الذين يطيعونه سبب خلاص أبدي،","مدعوا من االله رئيس كهنة على رتبة ملكي صادق.","الذي من جهته الكلام كثير عندنا، وعسر التفسير لننطق به، إذ قد صرتم متباطئي المسامع.","لأنكم إذ كان ينبغي أن تكونوا معلمين لسبب طول الزمان، تحتاجون أن يعلمكم أحد ما هي أركان بداءة أقوال االله، وصرتم محتاجين إلى اللبن لا إلى طعام قوي.","لأن كل من يتناول اللبن هو عديم الخبرة في كلام البر لأنه طفل،","وأما الطعام القوي فللبالغين، الذين بسبب التمرن قد صارت لهم الحواس مدربة على التمييز بين الخير والشر."],["لذلك ونحن تاركون كلام بداءة المسيح لنتقدم إلى الكمال، غير واضعين أيضا أساس التوبة من الأعمال الميتة، والإيمان باالله،","تعليم المعموديات، ووضع الأيادي، قيامة الأموات، والدينونة الأبدية -","وهذا سنفعله إن أذن االله.","لأن الذين استنيروا مرة، وذاقوا الموهبة السماوية وصاروا شركاء الروح القدس،","وذاقوا كلمة االله الصالحة وقوات الدهر الآتي،","وسقطوا، لا يمكن تجديدهم أيضا للتوبة، إذ هم يصلبون لأنفسهم ابن االله ثانية ويشهرونه.","لأن أرضا قد شربت المطر الآتي عليها مرارا كثيرة، وأنتجت عشبا صالحا للذين فلحت من أجلهم، تنال بركة من االله.","ولكن إن أخرجت شوكا وحسكا، فهي مرفوضة وقريبة من اللعنة، التي نهايتها للحريق.","ولكننا قد تيقنا من جهتكم أيها الأحباء أمورا أفضل، ومختصة بالخلاص، وإن كنا نتكلم هكذا.","لأن االله ليس بظالم حتى ينسى عملكم وتعب المحبة التي أظهرتموها نحو اسمه، إذ قد خدمتم القديسين وتخدمونهم.","ولكننا نشتهي أن كل واحد منكم يظهر هذا الاجتهاد عينه ليقين الرجاء إلى النهاية،","لكي لا تكونوا متباطئين بل متمثلين بالذين بالإيمان والأناة يرثون المواعيد.","فإنه لما وعد االله إبراهيم، إذ لم يكن له أعظم يقسم به، أقسم بنفسه،","قائلا: »إني لأباركنك بركة وأكثرنك تكثيرا«.","وهكذا إذ تأنى نال الموعد.","فإن الناس يقسمون بالأعظم، ونهاية كل مشاجرة عندهم لأجل التثبيت هي القسم.","فلذلك إذ أراد االله أن يظهر أكثر كثيرا لورثة الموعد عدم تغير قضائه، توسط بقسم،","حتى بأمرين عديمي التغير، لا يمكن أن االله يكذب فيهما، تكون لنا تعزية قوية، نحن الذين التجأنا لنمسك بالرجاء الموضوع أمامنا،","الذي هو لنا كمرساة للنفس مؤتمنة وثابتة، تدخل إلى ما داخل الحجاب،","حيث دخل يسوع كسابق لأجلنا، صائرا على رتبة ملكي صادق، رئيس كهنة إلى الأبد."],["لأن ملكي صادق هذا، ملك ساليم، كاهن االله العلي، الذي استقبل إبراهيم راجعا من كسرة الملوك وباركه،","الذي قسم له إبراهيم عشرا من كل شيء. المترجم أولا »ملك البر« ثم أيضا »ملك ساليم« أي ملك السلام","بلا أب بلا أم بلا نسب. لا بداءة أيام له ولا نهاية حياة. بل هو مشبه بابن االله. هذا يبقى كاهنا إلى الأبد.","ثم انظروا ما أعظم هذا الذي أعطاه إبراهيم رئيس الآباء عشرا أيضا من رأس الغنائم.","وأما الذين هم من بني لاوي، الذين يأخذون الكهنوت، فلهم وصية أن يعشروا الشعب بمقتضى الناموس - أي إخوتهم، مع أنهم قد خرجوا من صلب إبراهيم.","ولكن الذي ليس له نسب منهم قد عشر إبراهيم، وبارك الذي له المواعيد!","وبدون كل مشاجرة: الأكبر يبارك الأصغر.","وهنا أناس مائتون يأخذون عشرا، وأما هناك فالمشهود له بأنه حي.","حتى أقول كلمة: إن لاوي أيضا الآخذ الأعشار قد عشر بإبراهيم!","لأنه كان بعد في صلب أبيه حين استقبله ملكي صادق.","فلو كان بالكهنوت اللاوي كمال - إذ الشعب أخذ الناموس عليه - ماذا كانت الحاجة بعد إلى أن يقوم كاهن آخر على رتبة ملكي صادق، ولا يقال »على رتبة هارون«؟","لأنه إن تغير الكهنوت فبالضرورة يصير تغير للناموس أيضا.","لأن الذي يقال عنه هذا كان شريكا في سبط آخر لم يلازم أحد منه المذبح.","فإنه واضح أن ربنا قد طلع من سبط يهوذا، الذي لم يتكلم عنه موسى شيئا من جهة الكهنوت.","وذلك أكثر وضوحا أيضا إن كان على شبه ملكي صادق يقوم كاهن آخر،","قد صار ليس بحسب ناموس وصية جسدية، بل بحسب قوة حياة لا تزول.","لأنه يشهد أنك »كاهن إلى الأبد على رتبة ملكي صادق«.","فإنه يصير إبطال الوصية السابقة من أجل ضعفها وعدم نفعها،","إذ الناموس لم يكمل شيئا. ولكن يصير إدخال رجاء أفضل به نقترب إلى االله.","وعلى قدر ما إنه ليس بدون قسم -","لأن أولئك بدون قسم قد صاروا كهنة، وأما هذا فبقسم من القائل له: »أقسم الرب ولن يندم، أنت كاهن إلى الأبد على رتبة ملكي صادق«.","على قدر ذلك قد صار يسوع ضامنا لعهد أفضل.","وأولئك قد صاروا كهنة كثيرين لأن الموت منعهم من البقاء،","وأما هذا فلأنه يبقى إلى الأبد، له كهنوت لا يزول.","فمن ثم يقدر أن يخلص أيضا إلى التمام الذين يتقدمون به إلى االله، إذ هو حي في كل حين ليشفع فيهم.","لأنه كان يليق بنا رئيس كهنة مثل هذا، قدوس بلا شر ولا دنس، قد انفصل عن الخطاة وصار أعلى من السماوات","الذي ليس له اضطرار كل يوم مثل رؤساء الكهنة أن يقدم ذبائح أولا عن خطايا نفسه ثم عن خطايا الشعب، لأنه فعل هذا مرة واحدة، إذ قدم نفسه.","فإن الناموس يقيم أناسا بهم ضعف رؤساء كهنة. وأما كلمة القسم التي بعد الناموس فتقيم ابنا مكملا إلى الأبد."],["وأما رأس الكلام فهو أن لنا رئيس كهنة مثل هذا ،قد جلس في يمين عرش العظمة في السماوات","خادما للأقداس والمسكن الحقيقي الذي نصبه الرب لا إنسان.","لأن كل رئيس كهنة يقام لكي يقدم قرابين وذبائح. فمن ثم يلزم أن يكون لهذا أيضا شيء يقدمه.","فإنه لو كان على الأرض لما كان كاهنا، إذ يوجد الكهنة الذين يقدمون قرابين حسب الناموس،","الذين يخدمون شبه السماويات وظلها، كما أوحي إلى موسى وهو مزمع أن يصنع المسكن. لأنه قال: »انظر أن تصنع كل شيء حسب المثال الذي أظهر لك في الجبل«.","ولكنه الآن قد حصل على خدمة أفضل بمقدار ما هو وسيط أيضا لعهد أعظم، قد تثبت على مواعيد أفضل.","فإنه لو كان ذلك الأول بلا عيب لما طلب موضع لثان.","لأنه يقول لهم لائما: »هوذا أيام تأتي يقول الرب، حين أكمل مع بيت إسرائيل ومع بيت يهوذا عهدا جديدا.","لا كالعهد الذي عملته مع آبائهم يوم أمسكت بيدهم لأخرجهم من أرض مصر، لأنهم لم يثبتوا في عهدي، وأنا أهملتهم يقول الرب.","لأن هذا هو العهد الذي أعهده مع بيت إسرائيل بعد تلك الأيام يقول الرب: أجعل نواميسي في أذهانهم، وأكتبها على قلوبهم، وأنا أكون لهم إلها وهم يكونون لي شعبا.","ولا يعلمون كل واحد قريبه وكل واحد أخاه قائلا: اعرف الرب، لأن الجميع سيعرفونني من صغيرهم إلى كبيرهم.","لأني أكون صفوحا عن آثامهم، ولا أذكر خطاياهم وتعدياتهم في ما بعد«.","فإذ قال »جديدا« عتق الأول. وأما ما عتق وشاخ فهو قريب من الاضمحلال."],["ثم العهد الأول كان له أيضا فرائض خدمة والقدس العالمي،","لأنه نصب المسكن الأول الذي يقال له »القدس« الذي كان فيه المنارة، والمائدة، وخبز التقدمة.","ووراء الحجاب الثاني المسكن الذي يقال له »قدس الأقداس«","فيه مبخرة من ذهب، وتابوت العهد مغشى من كل جهة بالذهب، الذي فيه قسط من ذهب فيه المن، وعصا هارون التي أفرخت، ولوحا العهد.","وفوقه كروبا المجد مظللين الغطاء. أشياء ليس لنا الآن أن نتكلم عنها بالتفصيل.","ثم إذ صارت هذه مهيأة هكذا، يدخل الكهنة إلى المسكن الأول كل حين، صانعين الخدمة.","وأما إلى الثاني فرئيس الكهنة فقط مرة في السنة، ليس بلا دم يقدمه عن نفسه وعن جهالات الشعب،","معلنا الروح القدس بهذا أن طريق الأقداس لم يظهر بعد، ما دام المسكن الأول له إقامة،","الذي هو رمز للوقت الحاضر، الذي فيه تقدم قرابين وذبائح لا يمكن من جهة الضمير أن تكمل الذي يخدم،","وهي قائمة بأطعمة وأشربة وغسلات مختلفة وفرائض جسدية فقط، موضوعة إلى وقت الإصلاح.","وأما المسيح، وهو قد جاء رئيس كهنة للخيرات العتيدة، فبالمسكن الأعظم والأكمل، غير المصنوع بيد، أي الذي ليس من هذه الخليقة.","وليس بدم تيوس وعجول، بل بدم نفسه، دخل مرة واحدة إلى الأقداس، فوجد فداء أبديا.","لأنه إن كان دم ثيران وتيوس ورماد عجلة مرشوش على المنجسين يقدس إلى طهارة الجسد،","فكم بالحري يكون دم المسيح، الذي بروح أزلي قدم نفسه لله بلا عيب، يطهر ضمائركم من أعمال ميتة لتخدموا االله الحي!","ولأجل هذا هو وسيط عهد جديد، لكي يكون المدعوون - إذ صار موت لفداء التعديات التي في العهد الأول - ينالون وعد الميراث الأبدي.","لأنه حيث توجد وصية يلزم بيان موت الموصي.","لأن الوصية ثابتة على الموتى، إذ لا قوة لها البتة ما دام الموصي حيا.","فمن ثم الأول أيضا لم يكرس بلا دم،","لأن موسى بعدما كلم جميع الشعب بكل وصية بحسب الناموس، أخذ دم العجول والتيوس، مع ماء وصوفا قرمزيا وزوفا، ورش الكتاب نفسه وجميع الشعب،","قائلا: »هذا هو دم العهد الذي أوصاكم االله به«.","والمسكن أيضا وجميع آنية الخدمة رشها كذلك بالدم.","وكل شيء تقريبا يتطهر حسب الناموس بالدم، وبدون سفك دم لا تحصل مغفرة!","فكان يلزم أن أمثلة الأشياء التي في السماوات تطهر بهذه، وأما السماويات عينها فبذبائح أفضل من هذه.","لأن المسيح لم يدخل إلى أقداس مصنوعة بيد أشباه الحقيقية، بل إلى السماء عينها، ليظهر الآن أمام وجه االله لأجلنا.","ولا ليقدم نفسه مرارا كثيرة، كما يدخل رئيس الكهنة إلى الأقداس كل سنة بدم آخر.","فإذ ذاك كان يجب أن يتألم مرارا كثيرة منذ تأسيس العالم، ولكنه الآن قد أظهر مرة عند انقضاء الدهور ليبطل الخطية بذبيحة نفسه.","وكما وضع للناس أن يموتوا مرة ثم بعد ذلك الدينونة،","هكذا المسيح أيضا، بعدما قدم مرة لكي يحمل خطايا كثيرين، سيظهر ثانية بلا خطية للخلاص للذين ينتظرونه."],["لأن الناموس، إذ له ظل الخيرات العتيدة لا نفس صورة الأشياء، لا يقدر أبدا بنفس الذبائح كل سنة، التي يقدمونها على الدوام، أن يكمل الذين يتقدمون.","وإلا، أفما زالت تقدم؟ من أجل أن الخادمين، وهم مطهرون مرة، لا يكون لهم أيضا ضمير خطايا.","لكن فيها كل سنة ذكر خطايا.","لأنه لا يمكن أن دم ثيران وتيوس يرفع خطايا.","لذلك عند دخوله إلى العالم يقول: »ذبيحة وقربانا لم ترد، ولكن هيأت لي جسدا.","بمحرقات وذبائح للخطية لم تسر.","ثم قلت: هئنذا أجيء. في درج الكتاب مكتوب عني، لأفعل مشيئتك يا أالله«.","إذ يقول آنفا: »إنك ذبيحة وقربانا ومحرقات وذبائح للخطية لم ترد ولا سررت بها«. التي تقدم حسب الناموس.","ثم قال: »هئنذا أجيء لأفعل مشيئتك يا أالله«. ينزع الأول لكي يثبت الثاني.","فبهذه المشيئة نحن مقدسون بتقديم جسد يسوع المسيح مرة واحدة.","وكل كاهن يقوم كل يوم يخدم ويقدم مرارا كثيرة تلك الذبائح عينها، التي لا تستطيع البتة أن تنزع الخطية.","وأما هذا فبعدما قدم عن الخطايا ذبيحة واحدة، جلس إلى الأبد عن يمين االله،","منتظرا بعد ذلك حتى توضع أعداؤه موطئا لقدميه.","لأنه بقربان واحد قد أكمل إلى الأبد المقدسين.","ويشهد لنا الروح القدس أيضا. لأنه بعدما قال سابقا:","»هذا هو العهد الذي أعهده معهم بعد تلك الأيام، يقول الرب، أجعل نواميسي في قلوبهم وأكتبها في أذهانهم«","و: »لن أذكر خطاياهم وتعدياتهم في ما بعد«.","وإنما حيث تكون مغفرة لهذه لا يكون بعد قربان عن الخطية.","فإذ لنا أيها الإخوة ثقة بالدخول إلى »الأقداس« بدم يسوع،","طريقا كرسه لنا حديثا حيا، بالحجاب، أي جسده،","وكاهن عظيم على بيت االله،","لنتقدم بقلب صادق في يقين الإيمان، مرشوشة قلوبنا من ضمير شرير، ومغتسلة أجسادنا بماء نقي.","لنتمسك بإقرار الرجاء راسخا، لأن الذي وعد هو أمين.","ولنلاحظ بعضنا بعضا للتحريض على المحبة والأعمال الحسنة،","غير تاركين اجتماعنا كما لقوم عادة، بل واعظين بعضنا بعضا، وبالأكثر على قدر ما ترون اليوم يقرب،","فإنه إن أخطأنا باختيارنا بعدما أخذنا معرفة الحق، لا تبقى بعد ذبيحة عن الخطايا،","بل قبول دينونة مخيف، وغيرة نار عتيدة أن تأكل المضادين.","من خالف ناموس موسى فعلى شاهدين أو ثلاثة شهود يموت بدون رأفة.","فكم عقابا أشر تظنون أنه يحسب مستحقا من داس ابن االله، وحسب دم العهد الذي قدس به دنسا، وازدرى بروح النعمة؟","فإننا نعرف الذي قال: »لي الانتقام، أنا أجازي، يقول الرب«. وأيضا: »الرب يدين شعبه«.","مخيف هو الوقوع في يدي االله الحي!","ولكن تذكروا الأيام السالفة التي فيها بعدما أنرتم صبرتم على مجاهدة آلام كثيرة.","من جهة مشهورين بتعييرات وضيقات، ومن جهة صائرين شركاء الذين تصرف فيهم هكذا.","لأنكم رثيتم لقيودي أيضا، وقبلتم سلب أموالكم بفرح، عالمين في أنفسكم أن لكم مالا أفضل في السماوات وباقيا.","فلا تطرحوا ثقتكم التي لها مجازاة عظيمة.","لأنكم تحتاجون إلى الصبر، حتى إذا صنعتم مشيئة االله تنالون الموعد.","لأنه بعد قليل جدا »سيأتي الآتي ولا يبطئ.","أما البار فبالإيمان يحيا، وإن ارتد لا تسر به نفسي«.","وأما نحن فلسنا من الارتداد للهلاك، بل من الإيمان لاقتناء النفس."],["وأما الإيمان فهو الثقة بما يرجى والإيقان بأمور لا ترى.","فإنه في هذا شهد للقدماء.","بالإيمان نفهم أن العالمين أتقنت بكلمة االله، حتى لم يتكون ما يرى مما هو ظاهر.","بالإيمان قدم هابيل لله ذبيحة أفضل من قايين، فبه شهد له أنه بار، إذ شهد االله لقرابينه. وبه، وإن مات، يتكلم بعد!","بالإيمان نقل أخنوخ لكي لا يرى الموت، ولم يوجد لأن االله نقله - إذ قبل نقله شهد له بأنه قد أرضى االله.","ولكن بدون إيمان لا يمكن إرضاؤه، لأنه يجب أن الذي يأتي إلى االله يؤمن بأنه موجود، وأنه يجازي الذين يطلبونه.","بالإيمان نوح لما أوحي إليه عن أمور لم تر بعد خاف، فبنى فلكا لخلاص بيته، فبه دان العالم، وصار وارثا للبر الذي حسب الإيمان.","بالإيمان إبراهيم لما دعي أطاع أن يخرج إلى المكان الذي كان عتيدا أن يأخذه ميراثا، فخرج وهو لا يعلم إلى أين يأتي.","بالإيمان تغرب في أرض الموعد كأنها غريبة، ساكنا في خيام مع إسحاق ويعقوب الوارثين معه لهذا الموعد عينه.","لأنه كان ينتظر المدينة التي لها الأساسات، التي صانعها وبارئها االله.","بالإيمان سارة نفسها أيضا أخذت قدرة على إنشاء نسل، وبعد وقت السن ولدت، إذ حسبت الذي وعد صادقا.","لذلك ولد أيضا من واحد، وذلك من ممات، مثل نجوم السماء في الكثرة، وكالرمل الذي على شاطئ البحر الذي لا يعد.","في الإيمان مات هؤلاء أجمعون، وهم لم ينالوا المواعيد، بل من بعيد نظروها وصدقوها وحيوها، وأقروا بأنهم غرباء ونزلاء على الأرض.","فإن الذين يقولون مثل هذا يظهرون أنهم يطلبون وطنا.","فلو ذكروا ذلك الذي خرجوا منه، لكان لهم فرصة للرجوع.","ولكن الآن يبتغون وطنا أفضل، أي سماويا. لذلك لا يستحي بهم االله أن يدعى إلههم، لأنه أعد لهم مدينة.","بالإيمان قدم إبراهيم إسحاق وهو مجرب - قدم الذي قبل المواعيد، وحيده","الذي قيل له: »إنه بإسحاق يدعى لك نسل«.","إذ حسب أن االله قادر على الإقامة من الأموات أيضا، الذين منهم أخذه أيضا في مثال.","بالإيمان إسحاق بارك يعقوب وعيسو من جهة أمور عتيدة.","بالإيمان يعقوب عند موته بارك كل واحد من ابني يوسف، وسجد على رأس عصاه.","بالإيمان يوسف عند موته ذكر خروج بني إسرائيل وأوصى من جهة عظامه.","بالإيمان موسى، بعدما ولد، أخفاه أبواه ثلاثة أشهر، لأنهما رأيا الصبي جميلا، ولم يخشيا أمر الملك.","بالإيمان موسى لما كبر أبى أن يدعى ابن ابنة فرعون،","مفضلا بالأحرى أن يذل مع شعب االله على أن يكون له تمتع وقتي بالخطية،","حاسبا عار المسيح غنى أعظم من خزائن مصر، لأنه كان ينظر إلى المجازاة.","بالإيمان ترك مصر غير خائف من غضب الملك، لأنه تشدد، كأنه يرى من لا يرى.","بالإيمان صنع الفصح ورش الدم لئلا يمسهم الذي أهلك الأبكار.","بالإيمان اجتازوا في البحر الأحمر كما في اليابسة، الأمر الذي لما شرع فيه المصريون غرقوا.","بالإيمان سقطت أسوار أريحا بعدما طيف حولها سبعة أيام.","بالإيمان راحاب الزانية لم تهلك مع العصاة، إذ قبلت الجاسوسين بسلام.","وماذا أقول أيضا؟ لأنه يعوزني الوقت إن أخبرت عن جدعون، وباراق، وشمشون، ويفتاح، وداود، وصموئيل، والأنبياء،","الذين بالإيمان قهروا ممالك، صنعوا برا، نالوا مواعيد، سدوا أفواه أسود،","أطفأوا قوة النار، نجوا من حد السيف، تقووا من ضعف، صاروا أشداء في الحرب، هزموا جيوش غرباء،","أخذت نساء أمواتهن بقيامة. وآخرون عذبوا ولم يقبلوا النجاة لكي ينالوا قيامة أفضل.","وآخرون تجربوا في هزء وجلد، ثم في قيود أيضا وحبس.","رجموا، نشروا، جربوا، ماتوا قتلا بالسيف، طافوا في جلود غنم وجلود معزى، معتازين مكروبين مذلين،","وهم لم يكن العالم مستحقا لهم. تائهين في براري وجبال ومغاير وشقوق الأرض.","فهؤلاء كلهم، مشهودا لهم بالإيمان، لم ينالوا الموعد،","إذ سبق االله فنظر لنا شيئا أفضل، لكي لا يكملوا بدوننا."],["لذلك نحن أيضا إذ لنا سحابة من الشهود مقدار هذه محيطة بنا، لنطرح كل ثقل والخطية المحيطة بنا بسهولة، ولنحاضر بالصبر في الجهاد الموضوع أمامنا،","ناظرين إلى رئيس الإيمان ومكمله يسوع، الذي من أجل السرور الموضوع أمامه احتمل الصليب مستهينا بالخزي، فجلس في يمين عرش االله.","فتفكروا في الذي احتمل من الخطاة مقاومة لنفسه مثل هذه لئلا تكلوا وتخوروا في نفوسكم.","لم تقاوموا بعد حتى الدم مجاهدين ضد الخطية،","وقد نسيتم الوعظ الذي يخاطبكم كبنين: »يا ابني لا تحتقر تأديب الرب، ولا تخر إذا وبخك.","لأن الذي يحبه الرب يؤدبه، ويجلد كل ابن يقبله«.","إن كنتم تحتملون التأديب يعاملكم االله كالبنين. فأي ابن لا يؤدبه أبوه؟","ولكن إن كنتم بلا تأديب، قد صار الجميع شركاء فيه، فأنتم نغول لا بنون.","ثم قد كان لنا آباء أجسادنا مؤدبين، وكنا نهابهم. أفلا نخضع بالأولى جدا لأبي الأرواح، فنحيا؟","لأن أولئك أدبونا أياما قليلة حسب استحسانهم، وأما هذا فلأجل المنفعة، لكي نشترك في قداسته.","ولكن كل تأديب في الحاضر لا يرى أنه للفرح بل للحزن. وأما أخيرا فيعطي الذين يتدربون به ثمر بر للسلام.","لذلك قوموا الأيادي المسترخية والركب المخلعة،","واصنعوا لأرجلكم مسالك مستقيمة، لكي لا يعتسف الأعرج، بل بالحري يشفى.","اتبعوا السلام مع الجميع، والقداسة التي بدونها لن يرى أحد الرب.","ملاحظين لئلا يخيب أحد من نعمة االله. لئلا يطلع أصل مرارة ويصنع انزعاجا، فيتنجس به كثيرون.","لئلا يكون أحد زانيا أو مستبيحا كعيسو، الذي لأجل أكلة واحدة باع بكوريته.","فإنكم تعلمون أنه أيضا بعد ذلك، لما أراد أن يرث البركة رفض، إذ لم يجد للتوبة مكانا، مع أنه طلبها بدموع.","لأنكم لم تأتوا إلى جبل ملموس مضطرم بالنار، وإلى ضباب وظلام وزوبعة،","وهتاف بوق وصوت كلمات، استعفى الذين سمعوه من أن تزاد لهم كلمة،","لأنهم لم يحتملوا ما أمر به، وإن مست الجبل بهيمة ترجم أو ترمى بسهم.","وكان المنظر هكذا مخيفا حتى قال موسى: »أنا مرتعب ومرتعد!«.","بل قد أتيتم إلى جبل صهيون، وإلى مدينة االله الحي: أورشليم السماوية، وإلى ربوات هم محفل ملائكة،","وكنيسة أبكار مكتوبين في السماوات، وإلى االله ديان الجميع، وإلى أرواح أبرار مكملين،","وإلى وسيط العهد الجديد: يسوع، وإلى دم رش يتكلم أفضل من هابيل.","انظروا أن لا تستعفوا من المتكلم. لأنه إن كان أولئك لم ينجوا إذ استعفوا من المتكلم على الأرض، فبالأولى جدا لا ننجو نحن المرتدين عن الذي من السماء،","الذي صوته زعزع الأرض حينئذ، وأما الآن فقد وعد قائلا: »إني مرة أيضا أزلزل لا الأرض فقط بل السماء أيضا«.","فقوله »مرة أيضا« يدل على تغيير الأشياء المتزعزعة كمصنوعة، لكي تبقى التي لا تتزعزع.","لذلك ونحن قابلون ملكوتا لا يتزعزع ليكن عندنا شكر به نخدم االله خدمة مرضية، بخشوع وتقوى.","لأن إلهنا نار آكلة."],["لتثبت المحبة الأخوية.","لا تنسوا إضافة الغرباء، لأن بها أضاف أناس ملائكة وهم لا يدرون.","اذكروا المقيدين كأنكم مقيدون معهم، والمذلين كأنكم أنتم أيضا في الجسد.","ليكن الزواج مكرما عند كل واحد، والمضجع غير نجس. وأما العاهرون والزناة فسيدينهم االله.","لتكن سيرتكم خالية من محبة المال. كونوا مكتفين بما عندكم، لأنه قال: »لا أهملك ولا أتركك«","حتى إننا نقول واثقين: »الرب معين لي فلا أخاف. ماذا يصنع بي إنسان؟«","اذكروا مرشديكم الذين كلموكم بكلمة االله. انظروا إلى نهاية سيرتهم فتمثلوا بإيمانهم.","يسوع المسيح هو هو أمسا واليوم وإلى الأبد.","لا تساقوا بتعاليم متنوعة وغريبة، لأنه حسن أن يثبت القلب بالنعمة، لا بأطعمة لم ينتفع بها الذين تعاطوها.","لنا »مذبح« لا سلطان للذين يخدمون المسكن أن يأكلوا منه.","فإن الحيوانات التي يدخل بدمها عن الخطية إلى »الأقداس« بيد رئيس الكهنة تحرق أجسامها خارج المحلة.","لذلك يسوع أيضا، لكي يقدس الشعب بدم نفسه، تألم خارج الباب.","فلنخرج إذا إليه خارج المحلة حاملين عاره.","لأن ليس لنا هنا مدينة باقية، لكننا نطلب العتيدة.","فلنقدم به في كل حين لله ذبيحة التسبيح، أي ثمر شفاه معترفة باسمه.","ولكن لا تنسوا فعل الخير والتوزيع، لأنه بذبائح مثل هذه يسر االله.","أطيعوا مرشديكم واخضعوا، لأنهم يسهرون لأجل نفوسكم كأنهم سوف يعطون حسابا، لكي يفعلوا ذلك بفرح، لا آنين، لأن هذا غير نافع لكم.","صلوا لأجلنا، لأننا نثق أن لنا ضميرا صالحا، راغبين أن نتصرف حسنا في كل شيء.","ولكن أطلب أكثر أن تفعلوا هذا لكي أرد إليكم بأكثر سرعة.","وإله السلام الذي أقام من الأموات راعي الخراف العظيم، ربنا يسوع، بدم العهد الأبدي،","ليكملكم في كل عمل صالح لتصنعوا مشيئته، عاملا فيكم ما يرضي أمامه بيسوع المسيح، الذي له المجد إلى أبد الآبدين. آمين.","وأطلب إليكم أيها الإخوة أن تحتملوا كلمة الوعظ، لأني بكلمات قليلة كتبت إليكم.","اعلموا أنه قد أطلق الأخ تيموثاوس، الذي معه سوف أراكم، إن أتى سريعا.","سلموا على جميع مرشديكم وجميع القديسين. يسلم عليكم الذين من إيطاليا.","النعمة مع جميعكم. آمين )إلى العبرانيين، كتبت من إيطاليا، على يد تيموثاوس( رسالة يعقوب"]];
BBD["يعقوب"]=[["يعقوب، عبد الله والرب يسوع المسيح، يهدي السلام إلى الاثني عشر سبطا الذين في الشتات.","احسبوه كل فرح يا إخوتي حينما تقعون في تجارب متنوعة،","عالمين أن امتحان إيمانكم ينشئ صبرا.","وأما الصبر فليكن له عمل تام، لكي تكونوا تامين وكاملين غير ناقصين في شيء.","وإنما إن كان أحدكم تعوزه حكمة فليطلب من الله الذي يعطي الجميع بسخاء ولا يعير، فسيعطى له.","ولكن ليطلب بإيمان غير مرتاب البتة، لأن المرتاب يشبه موجا من البحر تخبطه الريح وتدفعه.","فلا يظن ذلك الإنسان أنه ينال شيئا من عند الرب.","رجل ذو رأيين هو متقلقل في جميع طرقه.","وليفتخر الأخ المتضع بارتفاعه،","وأما الغني فباتضاعه، لأنه كزهر العشب يزول.","لأن الشمس أشرقت بالحر، فيبست العشب، فسقط زهره وفني جمال منظره. هكذا يذبل الغني أيضا في طرقه.","طوبى للرجل الذي يحتمل التجربة، لأنه إذا تزكى ينال »إكليل الحياة« الذي وعد به الرب للذين يحبونه.","لا يقل أحد إذا جرب إني أجرب من قبل الله، لأن الله غير مجرب بالشرور وهو لا يجرب أحدا.","ولكن كل واحد يجرب إذا انجذب وانخدع من شهوته.","ثم الشهوة إذا حبلت تلد خطية، والخطية إذا كملت تنتج موتا.","لا تضلوا يا إخوتي الأحباء.","كل عطية صالحة وكل موهبة تامة هي من فوق، نازلة من عند أبي الأنوار، الذي ليس عنده تغيير ولا ظل دوران.","شاء فولدنا بكلمة الحق لكي نكون باكورة من خلائقه.","إذا يا إخوتي الأحباء، ليكن كل إنسان مسرعا في الاستماع، مبطئا في التكلم، مبطئا في الغضب،","لأن غضب الإنسان لا يصنع بر الله.","لذلك اطرحوا كل نجاسة وكثرة شر. فاقبلوا بوداعة الكلمة المغروسة القادرة أن تخلص نفوسكم.","ولكن كونوا عاملين بالكلمة، لا سامعين فقط خادعين نفوسكم.","لأنه إن كان أحد سامعا للكلمة وليس عاملا، فذاك يشبه رجلا ناظرا وجه خلقته في مرآة،","فإنه نظر ذاته ومضى، وللوقت نسي ما هو.","ولكن من اطلع على الناموس الكامل - ناموس الحرية - وثبت، وصار ليس سامعا ناسيا بل عاملا بالكلمة، فهذا يكون مغبوطا في عمله.","إن كان أحد فيكم يظن أنه دين، وهو ليس يلجم لسانه، بل يخدع قلبه، فديانة هذا باطلة.","الديانة الطاهرة النقية عند الله الآب هي هذه: افتقاد اليتامى والأرامل في ضيقتهم، وحفظ الإنسان نفسه بلا دنس من العالم."],["يا إخوتي، لا يكن لكم إيمان ربنا يسوع المسيح، رب المجد، في المحاباة.","فإنه إن دخل إلى مجمعكم رجل بخواتم ذهب في لباس بهي، ودخل أيضا فقير بلباس وسخ،","فنظرتم إلى اللابس اللباس البهي وقلتم له: »اجلس أنت هنا حسنا«. وقلتم للفقير: »قف أنت هناك« أو: »اجلس هنا تحت موطئ قدمي«","فهل لا ترتابون في أنفسكم، وتصيرون قضاة أفكار شريرة؟","اسمعوا يا إخوتي الأحباء، أما اختار الله فقراء هذا العالم أغنياء في الإيمان، وورثة الملكوت الذي وعد به الذين يحبونه؟","وأما أنتم فأهنتم الفقير. أليس الأغنياء يتسلطون عليكم وهم يجرونكم إلى المحاكم؟","أما هم يجدفون على الاسم الحسن الذي دعي به عليكم؟","فإن كنتم تكملون الناموس الملوكي حسب الكتاب »تحب قريبك كنفسك«. فحسنا تفعلون.","ولكن إن كنتم تحابون تفعلون خطية، موبخين من الناموس كمتعدين.","لأن من حفظ كل الناموس، وإنما عثر في واحدة، فقد صار مجرما في الكل.","لأن الذي قال: »لا تزن« قال أيضا: »لا تقتل«. فإن لم تزن ولكن قتلت، فقد صرت متعديا الناموس.","هكذا تكلموا وهكذا افعلوا كعتيدين أن تحاكموا بناموس الحرية.","لأن الحكم هو بلا رحمة لمن لم يعمل رحمة، والرحمة تفتخر على الحكم.","ما المنفعة يا إخوتي إن قال أحد إن له إيمانا ولكن ليس له أعمال؟ هل يقدر الإيمان أن يخلصه؟","إن كان أخ وأخت عريانين ومعتازين للقوت اليومي،","فقال لهما أحدكم: »امضيا بسلام، استدفئا واشبعا« ولكن لم تعطوهما حاجات الجسد، فما المنفعة؟","هكذا الإيمان أيضا، إن لم يكن له أعمال، ميت في ذاته.","لكن يقول قائل: »أنت لك إيمان، وأنا لي أعمال!« أرني إيمانك بدون أعمالك، وأنا أريك بأعمالي إيماني.","أنت تؤمن أن الله واحد. حسنا تفعل. والشياطين يؤمنون ويقشعرون!","ولكن هل تريد أن تعلم أيها الإنسان الباطل أن الإيمان بدون أعمال ميت؟","ألم يتبرر إبراهيم أبونا بالأعمال، إذ قدم إسحاق ابنه على المذبح؟","فترى أن الإيمان عمل مع أعماله، وبالأعمال أكمل الإيمان،","وتم الكتاب القائل: »فآمن إبراهيم بالله فحسب له برا« ودعي خليل الله.","ترون إذا أنه بالأعمال يتبرر الإنسان، لا بالإيمان وحده.","كذلك راحاب الزانية أيضا، أما تبررت بالأعمال، إذ قبلت الرسل وأخرجتهم في طريق آخر؟","لأنه كما أن الجسد بدون روح ميت، هكذا الإيمان أيضا بدون أعمال ميت."],["لا تكونوا معلمين كثيرين يا إخوتي، عالمين أننا نأخذ دينونة أعظم!","لأننا في أشياء كثيرة نعثر جميعنا. إن كان أحد لا يعثر في الكلام فذاك رجل كامل، قادر أن يلجم كل الجسد أيضا.","هوذا الخيل، نضع اللجم في أفواهها لكي تطاوعنا، فندير جسمها كله.","هوذا السفن أيضا، وهي عظيمة بهذا المقدار، وتسوقها رياح عاصفة، تديرها دفة صغيرة جدا إلى حيثما شاء قصد المدير.","هكذا اللسان أيضا، هو عضو صغير ويفتخر متعظما. هوذا نار قليلة، أي وقود تحرق؟","فاللسان نار! عالم الإثم. هكذا جعل في أعضائنا اللسان، الذي يدنس الجسم كله، ويضرم دائرة الكون، ويضرم من جهنم.","لأن كل طبع للوحوش والطيور والزحافات والبحريات يذلل، وقد تذلل للطبع البشري.","وأما اللسان فلا يستطيع أحد من الناس أن يذلله. هو شر لا يضبط، مملو سما مميتا.","به نبارك الله الآب، وبه نلعن الناس الذين قد تكونوا على شبه الله.","من الفم الواحد تخرج بركة ولعنة! لا يصلح يا إخوتي أن تكون هذه الأمور هكذا!","ألعل ينبوعا ينبع من نفس عين واحدة العذب والمر؟","هل تقدر يا إخوتي تينة أن تصنع زيتونا، أو كرمة تينا؟ ولا كذلك ينبوع يصنع ماء مالحا وعذبا!","من هو حكيم وعالم بينكم فلير أعماله بالتصرف الحسن في وداعة الحكمة.","ولكن إن كان لكم غيرة مرة وتحزب في قلوبكم، فلا تفتخروا وتكذبوا على الحق.","ليست هذه الحكمة نازلة من فوق، بل هي أرضية نفسانية شيطانية.","لأنه حيث الغيرة والتحزب هناك التشويش وكل أمر رديء.","وأما الحكمة التي من فوق فهي أولا طاهرة، ثم مسالمة، مترفقة، مذعنة، مملوة رحمة وأثمارا صالحة، عديمة الريب والرياء.","وثمر البر يزرع في السلام من الذين يفعلون السلام."],["ربة في أعضائكم؟","تشتهون ولستم تمتلكون. تقتلون وتحسدون ولستم تقدرون أن تنالوا. تخاصمون وتحاربون ولستم تمتلكون، لأنكم لا تطلبون.","تطلبون ولستم تأخذون، لأنكم تطلبون رديا لكي تنفقوا في لذاتكم.","أيها الزناة والزواني، أما تعلمون أن محبة العالم عداوة لله؟ فمن أراد أن يكون محبا للعالم فقد صار عدوا لله.","أم تظنون أن الكتاب يقول باطلا: الروح الذي حل فينا يشتاق إلى الحسد؟","ولكنه يعطي نعمة أعظم. لذلك يقول: »يقاوم الله المستكبرين، وأما المتواضعون فيعطيهم نعمة«.","فاخضعوا لله. قاوموا إبليس فيهرب منكم.","اقتربوا إلى الله فيقترب إليكم. نقوا أيديكم أيها الخطاة، وطهروا قلوبكم يا ذوي الرأيين.","اكتئبوا ونوحوا وابكوا. ليتحول ضحككم إلى نوح وفرحكم إلى غم.","اتضعوا قدام الرب فيرفعكم.","لا يذم بعضكم بعضا أيها الإخوة. الذي يذم أخاه ويدين أخاه يذم الناموس ويدين الناموس. وإن كنت تدين الناموس فلست عاملا بالناموس، بل ديانا له.","واحد هو واضع الناموس، القادر أن يخلص ويهلك. فمن أنت يا من تدين غيرك؟","هلم الآن أيها القائلون: »نذهب اليوم أو غدا إلى هذه المدينة أو تلك، وهناك نصرف سنة واحدة ونتجر ونربح«.","أنتم الذين لا تعرفون أمر الغد! لأنه ما هي حياتكم؟ إنها بخار، يظهر قليلا ثم يضمحل.","عوض أن تقولوا: »إن شاء الرب وعشنا نفعل هذا أو ذاك«.","وأما الآن فإنكم تفتخرون في تعظمكم. كل افتخار مثل هذا رديء.","فمن يعرف أن يعمل حسنا ولا يعمل، فذلك خطية له."],["هلم الآن أيها الأغنياء، ابكوا مولولين على شقاوتكم القادمة.","غناكم قد تهرأ، وثيابكم قد أكلها العث.","ذهبكم وفضتكم قد صدئا، وصدأهما يكون شهادة عليكم، ويأكل لحومكم كنار! قد كنزتم في الأيام الأخيرة.","هوذا أجرة الفعلة الذين حصدوا حقولكم المبخوسة منكم تصرخ، وصياح الحصادين قد دخل إلى أذني رب الجنود.","قد ترفهتم على الأرض وتنعمتم وربيتم قلوبكم، كما في يوم الذبح.","حكمتم على البار. قتلتموه. لا يقاومكم!","فتأنوا أيها الإخوة إلى مجيء الرب. هوذا الفلاح ينتظر ثمر الأرض الثمين متأنيا عليه حتى ينال المطر المبكر والمتأخر.","فتأنوا أنتم وثبتوا قلوبكم، لأن مجيء الرب قد اقترب.","لا يئن بعضكم على بعض أيها الإخوة لئلا تدانوا. هوذا الديان واقف قدام الباب.","خذوا يا إخوتي مثالا لاحتمال المشقات والأناة: الأنبياء الذين تكلموا باسم الرب.","ها نحن نطوب الصابرين. قد سمعتم بصبر أيوب ورأيتم عاقبة الرب. لأن الرب كثير الرحمة ورؤوف.","ولكن قبل كل شيء يا إخوتي لا تحلفوا لا بالسماء ولا بالأرض ولا بقسم آخر. بل لتكن نعمكم نعم ولاكم لا، لئلا تقعوا تحت دينونة.","أعلى أحد بينكم مشقات؟ فليصل. أمسرور أحد؟ فليرتل.","أمريض أحد بينكم؟ فليدع شيوخ الكنيسة فيصلوا عليه ويدهنوه بزيت باسم الرب،","وصلاة الإيمان تشفي المريض والرب يقيمه، وإن كان قد فعل خطية تغفر له.","اعترفوا بعضكم لبعض بالزلات، وصلوا بعضكم لأجل بعض لكي تشفوا. طلبة البار تقتدر كثيرا في فعلها.","كان إيليا إنسانا تحت الآلام مثلنا، وصلى صلاة أن لا تمطر، فلم تمطر على الأرض ثلاث سنين وستة أشهر.","ثم صلى أيضا فأعطت السماء مطرا وأخرجت الأرض ثمرها.","أيها الإخوة، إن ضل أحد بينكم عن الحق فرده أحد،","فليعلم أن من رد خاطئا عن ضلال طريقه يخلص نفسا من الموت، ويستر كثرة من الخطايا. رسالة بطرس الرسول الأولى"]];
BBD["بطرس الأولى"]=[["بطرس، رسول يسوع المسيح، إلى المتغربين من شتات بنتس وغلاطية وكبدوكية وأسيا وبيثينية، المختارين","بمقتضى علم االله الآب السابق، في تقديس الروح للطاعة، ورش دم يسوع المسيح. لتكثر لكم النعمة والسلام.","مبارك االله أبو ربنا يسوع المسيح، الذي حسب رحمته الكثيرة ولدنا ثانية لرجاء حي، بقيامة يسوع المسيح من الأموات،","لميراث لا يفنى ولا يتدنس ولا يضمحل، محفوظ في السماوات لأجلكم،","أنتم الذين بقوة االله محروسون، بإيمان، لخلاص مستعد أن يعلن في الزمان الأخير.","الذي به تبتهجون، مع أنكم الآن - إن كان يجب - تحزنون يسيرا بتجارب متنوعة،","لكي تكون تزكية إيمانكم، وهي أثمن من الذهب الفاني، مع أنه يمتحن بالنار، توجد للمدح والكرامة والمجد عند استعلان يسوع المسيح،","الذي وإن لم تروه تحبونه. ذلك وإن كنتم لا ترونه الآن لكن تؤمنون به، فتبتهجون بفرح لا ينطق به ومجيد،","نائلين غاية إيمانكم خلاص النفوس.","الخلاص الذي فتش وبحث عنه أنبياء، الذين تنبأوا عن النعمة التي لأجلكم،","باحثين أي وقت أو ما الوقت الذي كان يدل عليه روح المسيح الذي فيهم، إذ سبق فشهد بالآلام التي للمسيح والأمجاد التي بعدها.","الذين أعلن لهم أنهم ليس لأنفسهم، بل لنا كانوا يخدمون بهذه الأمور التي أخبرتم بها أنتم الآن بواسطة الذين بشروكم في الروح القدس المرسل من السماء. التي تشتهي الملائكة أن تطلع عليها.","لذلك منطقوا أحقاء ذهنكم صاحين، فألقوا رجاءكم بالتمام على النعمة التي يؤتى بها إليكم عند استعلان يسوع المسيح.","كأولاد الطاعة لا تشاكلوا شهواتكم السابقة في جهالتكم،","بل نظير القدوس الذي دعاكم، كونوا أنتم أيضا قديسين في كل سيرة.","لأنه مكتوب: »كونوا قديسين لأني أنا قدوس«.","وإن كنتم تدعون أبا الذي يحكم بغير محاباة حسب عمل كل واحد، فسيروا زمان غربتكم بخوف،","عالمين أنكم افتديتم لا بأشياء تفنى، بفضة أو ذهب، من سيرتكم الباطلة التي تقلدتموها من الآباء،","بل بدم كريم، كما من حمل بلا عيب ولا دنس، دم المسيح،","معروفا سابقا قبل تأسيس العالم، ولكن قد أظهر في الأزمنة الأخيرة من أجلكم،","أنتم الذين به تؤمنون باالله الذي أقامه من الأموات وأعطاه مجدا، حتى إن إيمانكم ورجاءكم هما في االله.","طهروا نفوسكم في طاعة الحق بالروح للمحبة الأخوية العديمة الرياء، فأحبوا بعضكم بعضا من قلب طاهر بشدة.","مولودين ثانية، لا من زرع يفنى، بل مما لا يفنى، بكلمة االله الحية الباقية إلى الأبد.","لأن كل جسد كعشب، وكل مجد إنسان كزهر عشب. العشب يبس وزهره سقط،","وأما كلمة الرب فتثبت إلى الأبد. وهذه هي الكلمة التي بشرتم بها."],["فاطرحوا كل خبث وكل مكر والرياء والحسد وكل مذمة،","وكأطفال مولودين الآن اشتهوا اللبن العقلي العديم الغش لكي تنموا به -","إن كنتم قد ذقتم أن الرب صالح.","الذي إذ تأتون إليه، حجرا حيا مرفوضا من الناس، ولكن مختار من االله كريم،","كونوا أنتم أيضا مبنيين كحجارة حية، بيتا روحيا، كهنوتا مقدسا، لتقديم ذبائح روحية مقبولة عند االله بيسوع المسيح.","لذلك يتضمن أيضا في الكتاب: »هئنذا أضع في صهيون حجر زاوية مختارا كريما، والذي يؤمن به لن يخزى«.","فلكم أنتم الذين تؤمنون الكرامة، وأما للذين لا يطيعون فالحجر الذي رفضه البناؤون هو قد صار رأس الزاوية،","وحجر صدمة وصخرة عثرة. الذين يعثرون غير طائعين للكلمة، الأمر الذي جعلوا له.","وأما أنتم فجنس مختار، وكهنوت ملوكي، أمة مقدسة، شعب اقتناء، لكي تخبروا بفضائل الذي دعاكم من الظلمة إلى نوره العجيب.","الذين قبلا لم تكونوا شعبا، وأما الآن فأنتم شعب االله. الذين كنتم غير مرحومين، وأما الآن فمرحومون.","أيها الأحباء، أطلب إليكم كغرباء ونزلاء أن تمتنعوا عن الشهوات الجسدية التي تحارب النفس،","وأن تكون سيرتكم بين الأمم حسنة، لكي يكونوا في ما يفترون عليكم كفاعلي شر يمجدون االله في يوم الافتقاد، من أجل أعمالكم الحسنة التي يلاحظونها.","فاخضعوا لكل ترتيب بشري من أجل الرب. إن كان للملك فكمن هو فوق الكل،","أو للولاة فكمرسلين منه للانتقام من فاعلي الشر، وللمدح لفاعلي الخير.","لأن هكذا هي مشيئة االله أن تفعلوا الخير فتسكتوا جهالة الناس الأغبياء.","كأحرار، وليس كالذين الحرية عندهم سترة للشر، بل كعبيد االله.","أكرموا الجميع. أحبوا الإخوة. خافوا االله. أكرموا الملك.","أيها الخدام، كونوا خاضعين بكل هيبة للسادة، ليس للصالحين المترفقين فقط، بل للعنفاء أيضا.","لأن هذا فضل إن كان أحد من أجل ضمير نحو االله يحتمل أحزانا متألما بالظلم.","لأنه أي مجد هو إن كنتم تلطمون مخطئين فتصبرون؟ بل إن كنتم تتألمون عاملين الخير فتصبرون، فهذا فضل عند االله،","لأنكم لهذا دعيتم. فإن المسيح أيضا تألم لأجلنا، تاركا لنا مثالا لكي تتبعوا خطواته.","الذي لم يفعل خطية، ولا وجد في فمه مكر،","الذي إذ شتم لم يكن يشتم عوضا وإذ تألم لم يكن يهدد بل كان يسلم لمن يقضي بعدل.","الذي حمل هو نفسه خطايانا في جسده على الخشبة، لكي نموت عن الخطايا فنحيا للبر. الذي بجلدته شفيتم.","لأنكم كنتم كخراف ضالة، لكنكم رجعتم الآن إلى راعي نفوسكم وأسقفها."],["كذلكن أيتها النساء كن خاضعات لرجالكن، حتى وإن كان البعض لا يطيعون الكلمة، يربحون بسيرة النساء بدون كلمة،","ملاحظين سيرتكن الطاهرة بخوف.","ولا تكن زينتكن الزينة الخارجية من ضفر الشعر والتحلي بالذهب ولبس الثياب،","بل إنسان القلب الخفي في العديمة الفساد، زينة الروح الوديع الهادئ، الذي هو قدام االله كثير الثمن.","فإنه هكذا كانت قديما النساء القديسات أيضا المتوكلات على االله، يزين أنفسهن خاضعات لرجالهن،","كما كانت سارة تطيع إبراهيم داعية إياه »سيدها«. التي صرتن أولادها، صانعات خيرا، وغير خائفات خوفا البتة.","كذلكم أيها الرجال كونوا ساكنين بحسب الفطنة مع الإناء النسائي كالأضعف، معطين إياهن كرامة كالوارثات أيضا معكم نعمة الحياة، لكي لا تعاق صلواتكم.","والنهاية، كونوا جميعا متحدي الرأي بحس واحد، ذوي محبة أخوية، مشفقين، لطفاء،","غير مجازين عن شر بشر أو عن شتيمة بشتيمة، بل بالعكس مباركين، عالمين أنكم لهذا دعيتم لكي ترثوا بركة.","لأن من أراد أن يحب الحياة ويرى أياما صالحة، فليكفف لسانه عن الشر وشفتيه أن تتكلما بالمكر،","ليعرض عن الشر ويصنع الخير، ليطلب السلام ويجد في أثره.","لأن عيني الرب على الأبرار وأذنيه إلى طلبتهم، ولكن وجه الرب ضد فاعلي الشر.","فمن يؤذيكم إن كنتم متمثلين بالخير؟","ولكن وإن تألمتم من أجل البر فطوباكم. وأما خوفهم فلا تخافوه ولا تضطربوا،","بل قدسوا الرب الإله في قلوبكم، مستعدين دائما لمجاوبة كل من يسألكم عن سبب الرجاء الذي فيكم بوداعة وخوف،","ولكم ضمير صالح، لكي يكون الذين يشتمون سيرتكم الصالحة في المسيح يخزون في ما يفترون عليكم كفاعلي شر.","لأن تألمكم إن شاءت مشيئة االله وأنتم صانعون خيرا، أفضل منه وأنتم صانعون شرا.","فإن المسيح أيضا تألم مرة واحدة من أجل الخطايا، البار من أجل الأثمة، لكي يقربنا إلى االله، مماتا في الجسد ولكن محيى في الروح،","الذي فيه أيضا ذهب فكرز للأرواح التي في السجن،","إذ عصت قديما، حين كانت أناة االله تنتظر مرة في أيام نوح، إذ كان الفلك يبنى، الذي فيه خلص قليلون، أي ثماني أنفس بالماء.","الذي مثاله يخلصنا نحن الآن، أي المعمودية. لا إزالة وسخ الجسد، بل سؤال ضمير صالح عن االله بقيامة يسوع المسيح،","الذي هو في يمين االله، إذ قد مضى إلى السماء، وملائكة وسلاطين وقوات مخضعة له."],["فإذ قد تألم المسيح لأجلنا بالجسد، تسلحوا أنتم أيضا بهذه النية. فإن من تألم في الجسد كف عن الخطية،","لكي لا يعيش أيضا الزمان الباقي في الجسد لشهوات الناس، بل لإرادة االله.","لأن زمان الحياة الذي مضى يكفينا لنكون قد عملنا إرادة الأمم، سالكين في الدعارة والشهوات، وإدمان الخمر، والبطر، والمنادمات، وعبادة الأوثان المحرمة،","الأمر الذي فيه يستغربون أنكم لستم تركضون معهم إلى فيض هذه الخلاعة عينها، مجدفين.","الذين سوف يعطون حسابا للذي هو على استعداد أن يدين الأحياء والأموات.","فإنه لأجل هذا بشر الموتى أيضا، لكي يدانوا حسب الناس بالجسد، ولكن ليحيوا حسب االله بالروح.","وإنما نهاية كل شيء قد اقتربت، فتعقلوا واصحوا للصلوات.","ولكن قبل كل شيء لتكن محبتكم بعضكم لبعض شديدة، لأن المحبة تستر كثرة من الخطايا.","كونوا مضيفين بعضكم بعضا بلا دمدمة.","ليكن كل واحد بحسب ما أخذ موهبة يخدم بها بعضكم بعضا، كوكلاء صالحين على نعمة االله المتنوعة.","إن كان يتكلم أحد فكأقوال االله، وإن كان يخدم أحد فكأنه من قوة يمنحها االله، لكي يتمجد االله في كل شيء بيسوع المسيح، الذي له المجد والسلطان إلى أبد الآبدين. آمين.","أيها الأحباء، لا تستغربوا البلوى المحرقة التي بينكم حادثة، لأجل امتحانكم، كأنه أصابكم أمر غريب،","بل كما اشتركتم في آلام المسيح افرحوا لكي تفرحوا في استعلان مجده أيضا مبتهجين.","إن عيرتم باسم المسيح فطوبى لكم، لأن روح المجد واالله يحل عليكم. أما من جهتهم فيجدف عليه، وأما من جهتكم فيمجد.","فلا يتألم أحدكم كقاتل، أو سارق، أو فاعل شر، أو متداخل في أمور غيره.","ولكن إن كان كمسيحي فلا يخجل، بل يمجد االله من هذا القبيل.","لأنه الوقت لابتداء القضاء من بيت االله. فإن كان أولا منا، فما هي نهاية الذين لا يطيعون إنجيل االله؟","وإن كان البار بالجهد يخلص، فالفاجر والخاطئ أين يظهران؟","فإذا، الذين يتألمون بحسب مشيئة االله فليستودعوا أنفسهم كما لخالق أمين في عمل الخير."],["أطلب إلى الشيوخ الذين بينكم، أنا الشيخ رفيقهم، والشاهد لآلام المسيح، وشريك المجد العتيد أن يعلن،","ارعوا رعية االله التي بينكم نظارا، لا عن اضطرار بل بالاختيار، ولا لربح قبيح بل بنشاط،","ولا كمن يسود على الأنصبة بل صائرين أمثلة للرعية،","ومتى ظهر رئيس الرعاة تنالون إكليل المجد الذي لا يبلى.","كذلك أيها الأحداث اخضعوا للشيوخ، وكونوا جميعا خاضعين بعضكم لبعض، وتسربلوا بالتواضع، لأن االله يقاوم المستكبرين، وأما المتواضعون فيعطيهم نعمة.","فتواضعوا تحت يد االله القوية لكي يرفعكم في حينه،","ملقين كل همكم عليه لأنه هو يعتني بكم.","اصحوا واسهروا لأن إبليس خصمكم كأسد زائر، يجول ملتمسا من يبتلعه هو.","فقاوموه راسخين في الإيمان، عالمين أن نفس هذه الآلام تجرى على إخوتكم الذين في العالم.","وإله كل نعمة الذي دعانا إلى مجده الأبدي في المسيح يسوع، بعدما تألمتم يسيرا، هو يكملكم، ويثبتكم، ويقويكم، ويمكنكم.","له المجد والسلطان إلى أبد الآبدين. آمين.","بيد سلوانس الأخ الأمين، كما أظن كتبت إليكم بكلمات قليلة واعظا وشاهدا، أن هذه هي نعمة االله الحقيقية التي فيها تقومون.","تسلم عليكم التي في بابل المختارة معكم، ومرقس ابني.","سلموا بعضكم على بعض بقبلة المحبة. سلام لكم جميعكم الذين في المسيح يسوع. آمين. رسالة بطرس الرسول الثانية"]];
BBD["بطرس الثانية"]=[["سمعان بطرس عبد يسوع المسيح ورسوله، إلى الذين نالوا معنا إيمانا ثمينا مساويا لنا، ببر إلهنا والمخلص يسوع المسيح.","لتكثر لكم النعمة والسلام بمعرفة الله ويسوع ربنا.","كما أن قدرته الإلهية قد وهبت لنا كل ما هو للحياة والتقوى، بمعرفة الذي دعانا بالمجد والفضيلة،","اللذين بهما قد وهب لنا المواعيد العظمى والثمينة لكي تصيروا بها شركاء الطبيعة الإلهية، هاربين من الفساد الذي في العالم بالشهوة.","ولهذا عينه وأنتم باذلون كل اجتهاد قدموا في إيمانكم فضيلة، وفي الفضيلة معرفة،","وفي المعرفة تعففا، وفي التعفف صبرا، وفي الصبر تقوى،","وفي التقوى مودة أخوية، وفي المودة الأخوية محبة.","لأن هذه إذا كانت فيكم وكثرت، تصيركم لا متكاسلين ولا غير مثمرين لمعرفة ربنا يسوع المسيح.","لأن الذي ليس عنده هذه هو أعمى قصير البصر، قد نسي تطهير خطاياه السالفة.","لذلك بالأكثر اجتهدوا أيها الإخوة أن تجعلوا دعوتكم واختياركم ثابتين. لأنكم إذا فعلتم ذلك لن تزلوا أبدا.","لأنه هكذا يقدم لكم بسعة دخول إلى ملكوت ربنا ومخلصنا يسوع المسيح الأبدي.","لذلك لا أهمل أن أذكركم دائما بهذه الأمور، وإن كنتم عالمين ومثبتين في الحق الحاضر.","ولكني أحسبه حقا ما دمت في هذا المسكن أن أنهضكم بالتذكرة،","عالما أن خلع مسكني قريب كما أعلن لي ربنا يسوع المسيح أيضا.","فأجتهد أيضا أن تكونوا بعد خروجي تتذكرون كل حين بهذه الأمور.","لأننا لم نتبع خرافات مصنعة إذ عرفناكم بقوة ربنا يسوع المسيح ومجيئه، بل قد كنا معاينين عظمته.","لأنه أخذ من الله الآب كرامة ومجدا، إذ أقبل عليه صوت كهذا من المجد الأسنى: »هذا هو ابني الحبيب الذي أنا سررت به«.","ونحن سمعنا هذا الصوت مقبلا من السماء إذ كنا معه في الجبل المقدس.","وعندنا الكلمة النبوية، وهي أثبت، التي تفعلون حسنا إن انتبهتم إليها كما إلى سراج منير في موضع مظلم، إلى أن ينفجر النهار ويطلع كوكب الصبح في قلوبكم،","عالمين هذا أولا: أن كل نبوة الكتاب ليست من تفسير خاص،","لأنه لم تأت نبوة قط بمشيئة إنسان، بل تكلم أناس الله القديسون مسوقين من الروح القدس."],["ولكن كان أيضا في الشعب أنبياء كذبة، كما سيكون فيكم أيضا معلمون كذبة، الذين يدسون بدع هلاك. وإذ هم ينكرون الرب الذي اشتراهم، يجلبون على أنفسهم هلاكا سريعا.","وسيتبع كثيرون تهلكاتهم. الذين بسببهم يجدف على طريق الحق.","وهم في الطمع يتجرون بكم بأقوال مصنعة، الذين دينونتهم منذ القديم لا تتوانى وهلاكهم لا ينعس.","لأنه إن كان الله لم يشفق على ملائكة قد أخطأوا، بل في سلاسل الظلام طرحهم في جهنم، وسلمهم محروسين للقضاء،","ولم يشفق على العالم القديم، بل إنما حفظ نوحا ثامنا كارزا للبر إذ جلب طوفانا على عالم الفجار.","وإذ رمد مدينتي سدوم وعمورة حكم عليهما بالانقلاب، واضعا عبرة للعتيدين أن يفجروا،","وأنقذ لوطا البار مغلوبا من سيرة الأردياء في الدعارة.","إذ كان البار بالنظر والسمع وهو ساكن بينهم يعذب يوما فيوما نفسه البارة بالأفعال الأثيمة.","يعلم الرب أن ينقذ الأتقياء من التجربة ويحفظ الأثمة إلى يوم الدين معاقبين،","ولا سيما الذين يذهبون وراء الجسد في شهوة النجاسة، ويستهينون بالسيادة. جسورون، معجبون بأنفسهم، لا يرتعبون أن يفتروا على ذوي الأمجاد","حيث ملائكة، وهم أعظم قوة وقدرة - لا يقدمون عليهم لدى الرب حكم افتراء.","أما هؤلاء فكحيوانات غير ناطقة، طبيعية، مولودة للصيد والهلاك، يفترون على ما يجهلون، فسيهلكون في فسادهم","آخذين أجرة الإثم. الذين يحسبون تنعم يوم لذة. أدناس وعيوب، يتنعمون في غرورهم صانعين ولائم معكم.","لهم عيون مملوة فسقا لا تكف عن الخطية، خادعون النفوس غير الثابتة. لهم قلب متدرب في الطمع. أولاد اللعنة.","قد تركوا الطريق المستقيم، فضلوا تابعين طريق بلعام بن بصور الذي أحب أجرة الإثم.","ولكنه حصل على توبيخ تعديه، إذ منع حماقة النبي حمار أعجم ناطقا بصوت إنسان.","هؤلاء هم آبار بلا ماء، غيوم يسوقها النوء. الذين قد حفظ لهم قتام الظلام إلى الأبد.","لأنهم إذ ينطقون بعظائم البطل، يخدعون بشهوات الجسد في الدعارة من هرب قليلا من الذين يسيرون في الضلال،","واعدين إياهم بالحرية، وهم أنفسهم عبيد الفساد. لأن ما انغلب منه أحد فهو له مستعبد أيضا!","لأنه إذا كانوا بعدما هربوا من نجاسات العالم، بمعرفة الرب والمخلص يسوع المسيح، يرتبكون أيضا فيها، فينغلبون، فقد صارت لهم الأواخر أشر من الأوائل.","لأنه كان خيرا لهم لو لم يعرفوا طريق البر، من أنهم بعدما عرفوا يرتدون عن الوصية المقدسة المسلمة لهم.","قد أصابهم ما في المثل الصادق: »كلب قد عاد إلى قيئه، وخنزيرة مغتسلة إلى مراغة الحمأة«."],["هذه أكتبها الآن إليكم رسالة ثانية أيها الأحباء، فيهما أنهض بالتذكرة ذهنكم النقي،","لتذكروا الأقوال التي قالها سابقا الأنبياء القديسون، ووصيتنا نحن الرسل، وصية الرب والمخلص.","عالمين هذا أولا: أنه سيأتي في آخر الأيام قوم مستهزئون، سالكين بحسب شهوات أنفسهم،","وقائلين: »أين هو موعد مجيئه؟ لأنه من حين رقد الآباء كل شيء باق هكذا من بدء الخليقة«.","لأن هذا يخفى عليهم بإرادتهم: أن السماوات كانت منذ القديم والأرض بكلمة الله قائمة من الماء وبالماء،","اللواتي بهن العالم الكائن حينئذ فاض عليه الماء فهلك.","وأما السماوات والأرض الكائنة الآن فهي مخزونة بتلك الكلمة عينها، محفوظة للنار إلى يوم الدين وهلاك الناس الفجار.","ولكن لا يخف عليكم هذا الشيء الواحد أيها الأحباء، أن يوما واحدا عند الرب كألف سنة، وألف سنة كيوم واحد.","لا يتباطأ الرب عن وعده كما يحسب قوم التباطؤ، لكنه يتأنى علينا، وهو لا يشاء أن يهلك أناس، بل أن يقبل الجميع إلى التوبة.","ولكن سيأتي كلص في الليل، يوم الرب، الذي فيه تزول السماوات بضجيج، وتنحل العناصر محترقة، وتحترق الأرض والمصنوعات التي فيها.","فبما أن هذه كلها تنحل، أي أناس يجب أن تكونوا أنتم في سيرة مقدسة وتقوى؟","منتظرين وطالبين سرعة مجيء يوم الرب، الذي به تنحل السماوات ملتهبة، والعناصر محترقة تذوب.","ولكننا بحسب وعده ننتظر سماوات جديدة وأرضا جديدة، يسكن فيها البر.","لذلك أيها الأحباء، إذ أنتم منتظرون هذه، اجتهدوا لتوجدوا عنده بلا دنس ولا عيب، في سلام.","واحسبوا أناة ربنا خلاصا، كما كتب إليكم أخونا الحبيب بولس أيضا بحسب الحكمة المعطاة له،","كما في الرسائل كلها أيضا، متكلما فيها عن هذه الأمور، التي فيها أشياء عسرة الفهم، يحرفها غير العلماء وغير الثابتين كباقي الكتب أيضا، لهلاك أنفسهم.","فأنتم أيها الأحباء إذ قد سبقتم فعرفتم، احترسوا من أن تنقادوا بضلال الأردياء فتسقطوا من ثباتكم.","ولكن انموا في النعمة وفي معرفة ربنا ومخلصنا يسوع المسيح. له المجد الآن وإلى يوم الدهر. آمين. رسالة يوحنا الرسول الأولى"]];
BBD["يوحنا الأولى"]=[["الذي كان من البدء، الذي سمعناه، الذي رأيناه بعيوننا، الذي شاهدناه، ولمسته أيدينا، من جهة كلمة الحياة.","فإن الحياة أظهرت، وقد رأينا ونشهد ونخبركم بالحياة الأبدية التي كانت عند الآب وأظهرت لنا.","الذي رأيناه وسمعناه نخبركم به، لكي يكون لكم أيضا شركة معنا. وأما شركتنا نحن فهي مع الآب ومع ابنه يسوع المسيح.","ونكتب إليكم هذا لكي يكون فرحكم كاملا.","وهذا هو الخبر الذي سمعناه منه ونخبركم به: إن االله نور وليس فيه ظلمة البتة.","إن قلنا إن لنا شركة معه وسلكنا في الظلمة، نكذب ولسنا نعمل الحق.","ولكن إن سلكنا في النور كما هو في النور، فلنا شركة بعضنا مع بعض، ودم يسوع المسيح ابنه يطهرنا من كل خطية.","إن قلنا إنه ليس لنا خطية نضل أنفسنا وليس الحق فينا.","إن اعترفنا بخطايانا فهو أمين وعادل، حتى يغفر لنا خطايانا ويطهرنا من كل إثم.","إن قلنا إننا لم نخطئ نجعله كاذبا، وكلمته ليست فينا."],["يا أولادي، أكتب إليكم هذا لكي لا تخطئوا. وإن أخطأ أحد فلنا شفيع عند الآب، يسوع المسيح البار.","وهو كفارة لخطايانا. ليس لخطايانا فقط، بل لخطايا كل العالم أيضا.","وبهذا نعرف أننا قد عرفناه: إن حفظنا وصاياه.","من قال قد عرفته وهو لا يحفظ وصاياه، فهو كاذب وليس الحق فيه.","وأما من حفظ كلمته، فحقا في هذا قد تكملت محبة االله. بهذا نعرف أننا فيه:","من قال إنه ثابت فيه، ينبغي أنه كما سلك ذاك هكذا يسلك هو أيضا.","أيها الإخوة، لست أكتب إليكم وصية جديدة، بل وصية قديمة كانت عندكم من البدء. الوصية القديمة هي الكلمة التي سمعتموها من البدء.","أيضا وصية جديدة أكتب إليكم، ما هو حق فيه وفيكم، أن الظلمة قد مضت، والنور الحقيقي الآن يضيء.","من قال إنه في النور وهو يبغض أخاه، فهو إلى الآن في الظلمة.","من يحب أخاه يثبت في النور وليس فيه عثرة.","وأما من يبغض أخاه فهو في الظلمة، وفي الظلمة يسلك، ولا يعلم أين يمضي، لأن الظلمة أعمت عينيه.","أكتب إليكم أيها الأولاد لأنه قد غفرت لكم الخطايا من أجل اسمه.","أكتب إليكم أيها الآباء لأنكم قد عرفتم الذي من البدء. أكتب إليكم أيها الأحداث لأنكم قد غلبتم الشرير. أكتب إليكم أيها الأولاد لأنكم قد عرفتم الآب.","كتبت إليكم أيها الآباء لأنكم قد عرفتم الذي من البدء. كتبت إليكم أيها الأحداث لأنكم أقوياء، وكلمة االله ثابتة فيكم، وقد غلبتم الشرير.","لا تحبوا العالم ولا الأشياء التي في العالم. إن أحب أحد العالم فليست فيه محبة الآب.","لأن كل ما في العالم شهوة الجسد، وشهوة العيون، وتعظم المعيشة، ليس من الآب بل من العالم.","والعالم يمضي وشهوته، وأما الذي يصنع مشيئة االله فيثبت إلى الأبد.","أيها الأولاد هي الساعة الأخيرة. وكما سمعتم أن ضد المسيح يأتي، قد صار الآن أضداد للمسيح كثيرون. من هنا نعلم أنها الساعة الأخيرة.","منا خرجوا، لكنهم لم يكونوا منا، لأنهم لو كانوا منا لبقوا معنا. لكن ليظهروا أنهم ليسوا جميعهم منا.","وأما أنتم فلكم مسحة من القدوس وتعلمون كل شيء.","لم أكتب إليكم لأنكم لستم تعلمون الحق، بل لأنكم تعلمونه، وأن كل كذب ليس من الحق.","من هو الكذاب، إلا الذي ينكر أن يسوع هو المسيح؟ هذا هو ضد المسيح، الذي ينكر الآب والابن.","كل من ينكر الابن ليس له الآب أيضا، ومن يعترف بالابن فله الآب أيضا.","أما أنتم فما سمعتموه من البدء فليثبت إذا فيكم. إن ثبت فيكم ما سمعتموه من البدء، فأنتم أيضا تثبتون في الابن وفي الآب.","وهذا هو الوعد الذي وعدنا هو به: الحياة الأبدية.","كتبت إليكم هذا عن الذين يضلونكم.","وأما أنتم فالمسحة التي أخذتموها منه ثابتة فيكم، ولا حاجة بكم إلى أن يعلمكم أحد، بل كما تعلمكم هذه المسحة عينها عن كل شيء، وهي حق وليست كذبا. كما علمتكم تثبتون فيه.","والآن أيها الأولاد، اثبتوا فيه، حتى إذا أظهر يكون لنا ثقة، ولا نخجل منه في مجيئه.","إن علمتم أنه بار هو، فاعلموا أن كل من يصنع البر مولود منه."],["أنظروا أية محبة أعطانا الآب حتى ندعى أولاد االله! من أجل هذا لا يعرفنا العالم، لأنه لا يعرفه.","أيها الأحباء، الآن نحن أولاد االله، ولم يظهر بعد ماذا سنكون. ولكن نعلم أنه إذا أظهر نكون مثله، لأننا سنراه كما هو.","وكل من عنده هذا الرجاء به، يطهر نفسه كما هو طاهر.","كل من يفعل الخطية يفعل التعدي أيضا. والخطية هي التعدي.","وتعلمون أن ذاك أظهر لكي يرفع خطايانا، وليس فيه خطية.","كل من يثبت فيه لا يخطئ. كل من يخطئ لم يبصره ولا عرفه.","أيها الأولاد، لا يضلكم أحد. من يفعل البر فهو بار، كما أن ذاك بار.","من يفعل الخطية فهو من إبليس، لأن إبليس من البدء يخطئ. لأجل هذا أظهر ابن االله لكي ينقض أعمال إبليس.","كل من هو مولود من االله لا يفعل خطية، لأن زرعه يثبت فيه، ولا يستطيع أن يخطئ لأنه مولود من االله.","بهذا أولاد االله ظاهرون وأولاد إبليس. كل من لا يفعل البر فليس من االله، وكذا من لا يحب أخاه.","لأن هذا هو الخبر الذي سمعتموه من البدء: أن يحب بعضنا بعضا -","ليس كما كان قايين من الشرير وذبح أخاه. ولماذا ذبحه؟ لأن أعماله كانت شريرة، وأعمال أخيه بارة.","لا تتعجبوا يا إخوتي إن كان العالم يبغضكم.","نحن نعلم أننا قد انتقلنا من الموت إلى الحياة لأننا نحب الإخوة. من لا يحب أخاه يبق في الموت.","كل من يبغض أخاه فهو قاتل نفس، وأنتم تعلمون أن كل قاتل نفس ليس له حياة أبدية ثابتة فيه.","بهذا قد عرفنا المحبة: أن ذاك وضع نفسه لأجلنا، فنحن ينبغي لنا أن نضع نفوسنا لأجل الإخوة.","وأما من كان له معيشة العالم، ونظر أخاه محتاجا، وأغلق أحشاءه عنه، فكيف تثبت محبة االله فيه؟","يا أولادي، لا نحب بالكلام ولا باللسان، بل بالعمل والحق!","وبهذا نعرف أننا من الحق ونسكن قلوبنا قدامه.","لأنه إن لامتنا قلوبنا فاالله أعظم من قلوبنا، ويعلم كل شيء.","أيها الأحباء، إن لم تلمنا قلوبنا فلنا ثقة من نحو االله.","ومهما سألنا ننال منه، لأننا نحفظ وصاياه، ونعمل الأعمال المرضية أمامه.","وهذه هي وصيته: أن نؤمن باسم ابنه يسوع المسيح، ونحب بعضنا بعضا كما أعطانا وصية.","ومن يحفظ وصاياه يثبت فيه وهو فيه. وبهذا نعرف أنه يثبت فينا: من الروح الذي أعطانا."],["أيها الأحباء، لا تصدقوا كل روح، بل امتحنوا الأرواح: هل هي من االله؟ لأن أنبياء كذبة كثيرين قد خرجوا إلى العالم.","بهذا تعرفون روح االله: كل روح يعترف بيسوع المسيح أنه قد جاء في الجسد فهو من االله،","وكل روح لا يعترف بيسوع المسيح أنه قد جاء في الجسد فليس من االله. وهذا هو روح ضد المسيح الذي سمعتم أنه يأتي، والآن هو في العالم.","أنتم من االله أيها الأولاد، وقد غلبتموهم لأن الذي فيكم أعظم من الذي في العالم.","هم من العالم. من أجل ذلك يتكلمون من العالم، والعالم يسمع لهم.","نحن من االله. فمن يعرف االله يسمع لنا، ومن ليس من االله لا يسمع لنا. من هذا نعرف روح الحق وروح الضلال.","أيها الأحباء، لنحب بعضنا بعضا، لأن المحبة هي من االله، وكل من يحب فقد ولد من االله ويعرف االله.","ومن لا يحب لم يعرف االله، لأن االله محبة.","بهذا أظهرت محبة االله فينا: أن االله قد أرسل ابنه الوحيد إلى العالم لكي نحيا به.","في هذا هي المحبة: ليس أننا نحن أحببنا االله، بل أنه هو أحبنا، وأرسل ابنه كفارة لخطايانا.","أيها الأحباء، إن كان االله قد أحبنا هكذا، ينبغي لنا أيضا أن يحب بعضنا بعضا.","االله لم ينظره أحد قط. إن أحب بعضنا بعضا فاالله يثبت فينا، ومحبته قد تكملت فينا.","بهذا نعرف أننا نثبت فيه وهو فينا: أنه قد أعطانا من روحه.","ونحن قد نظرنا ونشهد أن الآب قد أرسل الابن مخلصا للعالم.","من اعترف أن يسوع هو ابن االله، فاالله يثبت فيه وهو في االله.","ونحن قد عرفنا وصدقنا المحبة التي لله فينا. االله محبة، ومن يثبت في المحبة يثبت في االله واالله فيه.","بهذا تكملت المحبة فينا: أن يكون لنا ثقة في يوم الدين، لأنه كما هو في هذا العالم هكذا نحن أيضا.","لا خوف في المحبة، بل المحبة الكاملة تطرح الخوف إلى خارج لأن الخوف له عذاب. وأما من خاف فلم يتكمل في المحبة.","نحن نحبه لأنه هو أحبنا أولا.","إن قال أحد: »إني أحب االله« وأبغض أخاه، فهو كاذب. لأن من لا يحب أخاه الذي أبصره، كيف يقدر أن يحب االله الذي لم يبصره؟","ولنا هذه الوصية منه: أن من يحب االله يحب أخاه أيضا."],["كل من يؤمن أن يسوع هو المسيح فقد ولد من االله. وكل من يحب الوالد يحب المولود منه أيضا.","بهذا نعرف أننا نحب أولاد االله: إذا أحببنا االله وحفظنا وصاياه.","فإن هذه هي محبة االله: أن نحفظ وصاياه. ووصاياه ليست ثقيلة،","لأن كل من ولد من االله يغلب العالم. وهذه هي الغلبة التي تغلب العالم: إيماننا.","من هو الذي يغلب العالم، إلا الذي يؤمن أن يسوع هو ابن االله؟","هذا هو الذي أتى بماء ودم، يسوع المسيح. لا بالماء فقط، بل بالماء والدم. والروح هو الذي يشهد، لأن الروح هو الحق.","فإن الذين يشهدون في السماء هم ثلاثة: الآب، والكلمة، والروح القدس. وهؤلاء الثلاثة هم واحد.","والذين يشهدون في الأرض هم ثلاثة: الروح، والماء، والدم. والثلاثة هم في الواحد.","إن كنا نقبل شهادة الناس فشهادة االله أعظم، لأن هذه هي شهادة االله التي قد شهد بها عن ابنه.","من يؤمن بابن االله فعنده الشهادة في نفسه. من لا يصدق االله فقد جعله كاذبا، لأنه لم يؤمن بالشهادة التي قد شهد بها االله عن ابنه.","وهذه هي الشهادة: أن االله أعطانا حياة أبدية، وهذه الحياة هي في ابنه.","من له الابن فله الحياة، ومن ليس له ابن االله فليست له الحياة.","كتبت هذا إليكم أنتم المؤمنين باسم ابن االله لكي تعلموا أن لكم حياة أبدية، ولكي تؤمنوا باسم ابن االله.","وهذه هي الثقة التي لنا عنده: أنه إن طلبنا شيئا حسب مشيئته يسمع لنا.","وإن كنا نعلم أنه مهما طلبنا يسمع لنا، نعلم أن لنا الطلبات التي طلبناها منه.","إن رأى أحد أخاه يخطئ خطية ليست للموت، يطلب، فيعطيه حياة للذين يخطئون ليس للموت. توجد خطية للموت. ليس لأجل هذه أقول أن يطلب.","كل إثم هو خطية، وتوجد خطية ليست للموت.","نعلم أن كل من ولد من االله لا يخطئ، بل المولود من االله يحفظ نفسه، والشرير لا يمسه.","نعلم أننا نحن من االله، والعالم كله قد وضع في الشرير.","ونعلم أن ابن االله قد جاء وأعطانا بصيرة لنعرف الحق. ونحن في الحق في ابنه يسوع المسيح. هذا هو الإله الحق والحياة الأبدية.","أيها الأولاد احفظوا أنفسكم من الأصنام. آمين."]];
BBD["يوحنا الثانية"]=[["الشيخ، إلى كيرية المختارة، وإلى أولادها الذين أنا أحبهم بالحق، ولست أنا فقط، بل أيضا جميع الذين قد عرفوا الحق.","من أجل الحق الذي يثبت فينا وسيكون معنا إلى الأبد،","تكون معكم نعمة ورحمة وسلام من الله الآب ومن الرب يسوع المسيح، ابن الآب بالحق والمحبة.","فرحت جدا لأني وجدت من أولادك بعضا سالكين في الحق، كما أخذنا وصية من الآب.","والآن أطلب منك يا كيرية، لا كأني أكتب إليك وصية جديدة، بل التي كانت عندنا من البدء: أن يحب بعضنا بعضا.","وهذه هي المحبة، أن نسلك بحسب وصاياه. هذه هي الوصية، كما سمعتم من البدء أن تسلكوا فيها.","لأنه قد دخل إلى العالم مضلون كثيرون، لا يعترفون بيسوع المسيح آتيا في الجسد. هذا هو المضل، والضد للمسيح.","انظروا إلى أنفسكم لئلا نضيع ما عملناه، بل ننال أجرا تاما.","كل من تعدى ولم يثبت في تعليم المسيح فليس له االله. ومن يثبت في تعليم المسيح فهذا له الآب والابن جميعا.","إن كان أحد يأتيكم ولا يجيء بهذا التعليم، فلا تقبلوه في البيت، ولا تقولوا له سلام.","لأن من يسلم عليه يشترك في أعماله الشريرة.","إذ كان لي كثير لأكتب إليكم، لم أرد أن يكون بورق وحبر، لأني أرجو أن آتي إليكم وأتكلم فما لفم، لكي يكون فرحنا كاملا.","يسلم عليك أولاد أختك المختارة. آمين."]];
BBD["يوحنا الثالثة"]=[["الشيخ، إلى غايس الحبيب الذي أنا أحبه بالحق.","أيها الحبيب، في كل شيء أروم أن تكون ناجحا وصحيحا، كما أن نفسك ناجحة.","لأني فرحت جدا إذ حضر إخوة وشهدوا بالحق الذي فيك، كما أنك تسلك بالحق.","ليس لي فرح أعظم من هذا: أن أسمع عن أولادي أنهم يسلكون بالحق.","أيها الحبيب، أنت تفعل بالأمانة كل ما تصنعه إلى الإخوة وإلى الغرباء،","الذين شهدوا بمحبتك أمام الكنيسة. الذين تفعل حسنا إذا شيعتهم كما يحق الله،","لأنهم من أجل اسمه خرجوا وهم لا يأخذون شيئا من الأمم.","فنحن ينبغي لنا أن نقبل أمثال هؤلاء، لكي نكون عاملين معهم بالحق.","كتبت إلى الكنيسة، ولكن ديوتريفس - الذي يحب أن يكون الأول بينهم - لا يقبلنا.","من أجل ذلك إذا جئت فسأذكره بأعماله التي يعملها، هاذرا علينا بأقوال خبيثة. وإذ هو غير مكتف بهذه، لا يقبل الإخوة، ويمنع أيضا الذين يريدون، ويطردهم من الكنيسة.","أيها الحبيب، لا تتمثل بالشر بل بالخير، لأن من يصنع الخير هو من االله، ومن يصنع الشر فلم يبصر االله.","ديمتريوس مشهود له من الجميع ومن الحق نفسه، ونحن أيضا نشهد، وأنتم تعلمون أن شهادتنا هي صادقة.","وكان لي كثير لأكتبه، لكنني لست أريد أن أكتب إليك بحبر وقلم.","ولكنني أرجو أن أراك عن قريب فنتكلم فما لفم.","سلام لك. يسلم عليك الأحباء. سلم على الأحباء بأسمائهم."]];
BBD["يهوذا"]=[["يهوذا، عبد يسوع المسيح، وأخو يعقوب، إلى المدعوين المقدسين في االله الآب، والمحفوظين ليسوع المسيح.","لتكثر لكم الرحمة والسلام والمحبة.","أيها الأحباء، إذ كنت أصنع كل الجهد لأكتب إليكم عن الخلاص المشترك، اضطررت أن أكتب إليكم واعظا أن تجتهدوا لأجل الإيمان المسلم مرة للقديسين.","لأنه دخل خلسة أناس قد كتبوا منذ القديم لهذه الدينونة، فجار، يحولون نعمة إلهنا إلى الدعارة، وينكرون السيد الوحيد: االله وربنا يسوع المسيح.","فأريد أن أذكركم، ولو علمتم هذا مرة، أن الرب بعدما خلص الشعب من أرض مصر، أهلك أيضا الذين لم يؤمنوا.","والملائكة الذين لم يحفظوا رياستهم، بل تركوا مسكنهم حفظهم إلى دينونة اليوم العظيم بقيود أبدية تحت الظلام.","كما أن سدوم وعمورة والمدن التي حولهما، إذ زنت على طريق مثلهما ومضت وراء جسد آخر، جعلت عبرة مكابدة عقاب نار أبدية.","ولكن كذلك هؤلاء أيضا، المحتلمون، ينجسون الجسد، ويتهاونون بالسيادة، ويفترون على ذوي الأمجاد.","وأما ميخائيل رئيس الملائكة، فلما خاصم إبليس محاجا عن جسد موسى، لم يجسر أن يورد حكم افتراء، بل قال: »لينتهرك الرب«.","ولكن هؤلاء يفترون على ما لا يعلمون. وأما ما يفهمونه بالطبيعة، كالحيوانات غير الناطقة، ففي ذلك يفسدون.","ويل لهم لأنهم سلكوا طريق قايين، وانصبوا إلى ضلالة بلعام لأجل أجرة، وهلكوا في مشاجرة قورح.","هؤلاء صخور في ولائمكم المحبية، صانعين ولائم معا بلا خوف، راعين أنفسهم. غيوم بلا ماء تحملها الرياح. أشجار خريفية بلا ثمر ميتة مضاعفا، مقتلعة.","أمواج بحر هائجة مزبدة بخزيهم. نجوم تائهة محفوظ لها قتام الظلام إلى الأبد.","وتنبأ عن هؤلاء أيضا أخنوخ السابع من آدم قائلا: »هوذا قد جاء الرب في ربوات قديسيه","ليصنع دينونة على الجميع، ويعاقب جميع فجارهم على جميع أعمال فجورهم التي فجروا بها، وعلى جميع الكلمات الصعبة التي تكلم بها عليه خطاة فجار«.","هؤلاء هم مدمدمون متشكون، سالكون بحسب شهواتهم، وفمهم يتكلم بعظائم، يحابون بالوجوه من أجل المنفعة.","وأما أنتم أيها الأحباء فاذكروا الأقوال التي قالها سابقا رسل ربنا يسوع المسيح.","فإنهم قالوا لكم إنه في الزمان الأخير سيكون قوم مستهزئون، سالكين بحسب شهوات فجورهم.","هؤلاء هم المعتزلون بأنفسهم، نفسانيون لا روح لهم.","وأما أنتم أيها الأحباء فابنوا أنفسكم على إيمانكم الأقدس، مصلين في الروح القدس،","واحفظوا أنفسكم في محبة االله، منتظرين رحمة ربنا يسوع المسيح للحياة الأبدية.","وارحموا البعض مميزين،","وخلصوا البعض بالخوف مختطفين من النار، مبغضين حتى الثوب المدنس من الجسد.","والقادر أن يحفظكم غير عاثرين، ويوقفكم أمام مجده بلا عيب في الابتهاج،","الإله الحكيم الوحيد مخلصنا، له المجد والعظمة والقدرة والسلطان، الآن وإلى كل الدهور. آمين. رؤيا يوحنا اللاهوتي"]];
